    );
  }

  int _getStarCount() {
    if (hotelCategory.contains('2')) return 2;
    if (hotelCategory.contains('3')) return 3;
    if (hotelCategory.contains('4')) return 4;
    if (hotelCategory.contains('5')) return 5;
    if (hotelCategory.contains('6')) return 6;
    return 0;
  }

