  void _showSuccessDialogAndNavigate(BuildContext context) {
    showDialog(
      context: context,
      barrierDismissible: false,
      builder: (BuildContext context) {
        return AlertDialog(
          title: const Text('Registration Complete'),
          content: const Text(
            'Your hotel has been registered successfully!',
          ),
          actions: [
            SizedBox(
              width: double.infinity,
              child: ElevatedButton(
                style: ElevatedButton.styleFrom(
                  backgroundColor: Colors.blue,
                  padding: const EdgeInsets.symmetric(vertical: 14),
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(12),
                  ),
                ),
                onPressed: () async {
                  try {

                    final prefs = await SharedPreferences.getInstance();
                    final String usersJson = prefs.getString('registered_users') ?? '[]';


                    final List<dynamic> usersList = jsonDecode(usersJson);


                    List<Map<String, dynamic>> users = [];
                    for (var user in usersList) {
                      if (user is Map) {

                        Map<String, dynamic> safeUserMap = {};
                        user.forEach((key, value) {
                          safeUserMap[key.toString()] = _convertToJsonSafe(value);
                        });
                        users.add(safeUserMap);
                      }
                    }

                    String userEmail = registrationData['email']?.toString() ?? '';
                    if (userEmail.isEmpty && registrationData.containsKey('email')) {
                      userEmail = registrationData['email'].toString();
                    }


                    Map<String, dynamic> safeRegistrationData = _convertToJsonSafe(registrationData);


                    int userIndex = -1;
                    for (int i = 0; i < users.length; i++) {
                      if (users[i]['email'] == userEmail) {
                        userIndex = i;
                        break;
                      }
                    }

                    Map<String, dynamic> userData;

                    if (userIndex >= 0) {

                      userData = Map<String, dynamic>.from(users[userIndex]);


                      if (!userData.containsKey('hotels')) {
                        userData['hotels'] = [];
                      }


                      List<dynamic> hotels = List.from(userData['hotels'] ?? []);
                      hotels.add(safeRegistrationData);
                      userData['hotels'] = hotels;


                      userData['propertyType'] = 'hotel';


                      users[userIndex] = userData;
                    } else {

                      userData = {
                        'email': userEmail,
                        'fullName': registrationData['fullName']?.toString() ??
                            registrationData['ownerName']?.toString() ?? '',
                        'phone': registrationData['phone']?.toString() ??
                            registrationData['mobileNumber']?.toString() ?? '',
                        'propertyType': 'hotel',
                        'hotels': [safeRegistrationData],
                        'registeredAt': DateTime.now().toIso8601String(),
                      };


                      registrationData.forEach((key, value) {
                        if (!userData.containsKey(key)) {
                          userData[key] = _convertToJsonSafe(value);
                        }
                      });

                      users.add(userData);
                    }


                    await prefs.setString('registered_users', jsonEncode(users));

                    print('Navigating to OwnerDashboardScreen with:');
                    print('- User email: $userEmail');
                    print('- Hotels count: ${(userData['hotels'] as List).length}');


                    Navigator.of(context).pushAndRemoveUntil(
                      MaterialPageRoute(
                        builder: (context) => OwnerDashboardScreen(
                          userData: userData,
                          userEmail: userEmail,
                        ),
                      ),
                          (Route<dynamic> route) => false,
                    );
                  } catch (e) {
                    print('Error in navigation: $e');

                    Navigator.of(context).pop();
                    showDialog(
                      context: context,
                      builder: (context) => AlertDialog(
                        title: const Text('Error'),
                        content: Text('Failed to save registration: ${e.toString()}'),
                        actions: [
                          TextButton(
                            onPressed: () => Navigator.pop(context),
                            child: const Text('OK'),
                          ),
                        ],
                      ),
                    );
                  }
                },
                child: const Text(
                  'Go to Dashboard',
                  style: TextStyle(
                    fontSize: 16,
                    fontWeight: FontWeight.w600,
                    color: Colors.white,
                  ),
                ),
              ),
            ),
          ],
        );
      },
    );
  }

  dynamic _convertToJsonSafe(dynamic obj) {
    if (obj == null) {
      return null;
    }

    if (obj is DateTime) {
      return obj.toIso8601String();
    }

    if (obj is Uint8List) {
      return base64Encode(obj);
    }

    if (obj is Map) {
      Map<String, dynamic> result = {};
      obj.forEach((key, value) {
        result[key.toString()] = _convertToJsonSafe(value);
      });
      return result;
    }

    if (obj is List) {
      return obj.map((item) => _convertToJsonSafe(item)).toList();
    }

    if (obj is Set) {
      return obj.map((item) => _convertToJsonSafe(item)).toList();
    }

    // Handle primitive types and other objects
    if (obj is String || obj is num || obj is bool) {
      return obj;
    }

    // For any other object type, try to convert to string
    try {
      return obj.toString();
    } catch (e) {
      return null;
    }
  }

  String _getDeclarationText() {
    switch (hotelCategory) {
      case '2-Star':
        return 'I hereby confirm that all the information provided above is true and accurate.';
      case '3-Star':
      case '4-Star':
        return 'I hereby declare that the above information is true and correct. I agree to comply with all vendor terms.';
      case '5-Star':
      case '6-Star':
        return 'I hereby certify that all information provided above is true and correct. I agree to comply with all quality standards.';
      case 'Normal':
      default:
        return 'I hereby declare that the information provided above is true and correct to the best of my knowledge.';
    }
  }

  String _formatTime(String time) {
    if (time.isEmpty) return 'Not set';

    try {
      List<String> parts = time.split(':');
      if (parts.length >= 2) {
        int hour = int.parse(parts[0]);
        int minute = int.parse(parts[1]);
        String period = hour >= 12 ? 'PM' : 'AM';
        hour = hour % 12;
        if (hour == 0) hour = 12;
        return '${hour.toString().padLeft(2, '0')}:${minute.toString().padLeft(2, '0')} $period';
      }
    } catch (e) {

    }
    return time;
  }

  String _maskAccountNumber(String accountNumber) {
    if (accountNumber.length <= 4) return accountNumber;
    return 'XXXX XXXX ${accountNumber.substring(accountNumber.length - 4)}';
  }


  bool _isNormal() => hotelCategory == 'Normal';
  bool _isTwoStar() => hotelCategory == '2-Star';
  bool _isThreeStar() => hotelCategory == '3-Star';
  bool _isFourStar() => hotelCategory == '4-Star';
  bool _isFiveStar() => hotelCategory == '5-Star';
  bool _isSixStar() => hotelCategory == '6-Star';

  bool _isTwoStarOrAbove() =>
      _isTwoStar() ||
      _isThreeStar() ||
      _isFourStar() ||
      _isFiveStar() ||
      _isSixStar();
  bool _isThreeStarOrAbove() =>
      _isThreeStar() || _isFourStar() || _isFiveStar() || _isSixStar();
  bool _isFourStarOrAbove() => _isFourStar() || _isFiveStar() || _isSixStar();
  bool _isFiveStarOrAbove() => _isFiveStar() || _isSixStar();

