                        children: [
                          Text(
                            'Room Type',
                            style: TextStyle(fontSize: 12, color: _textLight),
                          ),
                          SizedBox(height: 4),
                          Container(
                            padding: EdgeInsets.symmetric(horizontal: 12),
                            decoration: BoxDecoration(
                              color: _cardBg,
