          fssaiLicense: widget.fssaiLicense,
          tradeLicense: widget.tradeLicense,
          aadharNumber: widget.aadharNumber,
          accountHolderName: widget.accountHolderName,
          bankName: widget.bankName,
          accountNumber: widget.accountNumber,
          ifscCode: widget.ifscCode,
          branch: widget.branch,
          accountType: widget.accountType,
          totalRooms: widget.totalRooms,
          personPhotoInfo: widget.personPhotoInfo,
          hotelType: widget.registrationData['hotelType'] ?? '',
          yearOfEstablishment:
              widget.registrationData['yearOfEstablishment'] ?? '',
          website: widget.registrationData['website'] ?? '',
          landmark: widget.registrationData['landmark'] ?? '',
          selectedRoomTypes: Map<String, bool>.from(
            widget.registrationData['selectedRoomTypes'] ?? {},
          ),
          roomDetails: Map<String, Map<String, dynamic>>.from(
            widget.registrationData['roomDetails'] ?? {},
          ),
          minTariff: widget.registrationData['minTariff'] ?? '',
          maxTariff: widget.registrationData['maxTariff'] ?? '',
          extraBedAvailable:
              widget.registrationData['extraBedAvailable'] ?? false,
          basicAmenities: Map<String, bool>.from(
            widget.registrationData['basicAmenities'] ?? {},
          ),
          hotelFacilities: Map<String, bool>.from(
            widget.registrationData['hotelFacilities'] ?? {},
          ),
          foodServices: Map<String, bool>.from(
            widget.registrationData['foodServices'] ?? {},
          ),
          additionalAmenities: Map<String, bool>.from(
            widget.registrationData['additionalAmenities'] ?? {},
          ),
          customAmenities: List<String>.from(
            widget.registrationData['customAmenities'] ?? [],
          ),
          alternateContact: widget.registrationData['alternateContact'] ?? '',
          landlineNumbers: List<String>.from(
            widget.registrationData['landlineNumbers'] ?? [],
          ),
          uploadedFiles: Map<String, Map<String, dynamic>>.from(
            widget.registrationData['uploadedFiles'] ?? {},
          ),
          signatureName: widget.registrationData['signatureName'] ?? '',
