    final occupancy =
        int.tryParse(details['occupancy']?.toString() ?? '0') ?? 0;
    final isAC = details['ac'] ?? true;
    final extraBed = details['extraBed'] ?? false;
    final extraBedPrice =
        double.tryParse(details['extraBedPrice']?.toString() ?? '0') ?? 0;

