            SizedBox(height: 12),
          ],
        ),

        ..._selectedRoomTypes.entries.where((entry) => entry.value).map((
          entry,
        ) {
          String roomType = entry.key;

          if (!_roomDetails.containsKey(roomType)) {
            _roomDetails[roomType] = {
              'rooms': '',
              'occupancy': '',
              'ac': true,
              'price': '',
              'extraBed': false,
              'extraBedPrice': '',
            };
          }

          final roomData = _roomDetails[roomType]!;

          return Container(
            margin: EdgeInsets.only(bottom: 16),
            child: _buildCard(
              title: '$roomType Details',
              children: [
                Row(
                  children: [
                    Expanded(
                      child: _buildSmallInput(
                        label: 'Number of Rooms',
                        controller: TextEditingController(
                          text: roomData['rooms'] ?? '',
                        ),
                        onChanged: (value) => roomData['rooms'] = value,
                        hint: '0',
                        keyboardType: TextInputType.number,
                      ),
                    ),
                    SizedBox(width: 12),
                    Expanded(
                      child: _buildSmallInput(
                        label: 'Max Occupancy',
                        controller: TextEditingController(
                          text: roomData['occupancy'] ?? '',
                        ),
                        onChanged: (value) => roomData['occupancy'] = value,
                        hint: 'Persons',
                        keyboardType: TextInputType.number,
                      ),
                    ),
                  ],
                ),
                SizedBox(height: 12),
                Row(
                  children: [
                    Expanded(
                      child: _buildSmallInput(
                        label: 'Price per Night (₹)',
                        controller: TextEditingController(
                          text: roomData['price'] ?? '',
                        ),
                        onChanged: (value) => roomData['price'] = value,
                        hint: '0',
                        keyboardType: TextInputType.number,
                      ),
                    ),
                    SizedBox(width: 12),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            'AC / Non-AC',
                            style: TextStyle(
                              fontSize: 12,
                              fontWeight: FontWeight.w500,
                            ),
                          ),
                          SizedBox(height: 8),
                          Row(
                            children: [
                              Expanded(
                                child: _buildToggleChip(
                                  'AC',
                                  roomData['ac'] ?? true,
                                  () => setState(() => roomData['ac'] = true),
                                ),
                              ),
                              SizedBox(width: 8),
                              Expanded(
                                child: _buildToggleChip(
                                  'Non-AC',
                                  !(roomData['ac'] ?? true),
                                  () => setState(() => roomData['ac'] = false),
                                ),
                              ),
                            ],
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
                SizedBox(height: 12),
                Row(
                  children: [
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            'Extra Bed Available',
                            style: TextStyle(
                              fontSize: 12,
                              fontWeight: FontWeight.w500,
                            ),
                          ),
                          SizedBox(height: 8),
                          Row(
                            children: [
                              _buildToggleChip(
                                'Yes',
                                roomData['extraBed'] ?? false,
                                () =>
                                    setState(() => roomData['extraBed'] = true),
                              ),
                              SizedBox(width: 8),
                              _buildToggleChip(
                                'No',
                                !(roomData['extraBed'] ?? false),
                                () => setState(
                                  () => roomData['extraBed'] = false,
                                ),
                              ),
                            ],
                          ),
                        ],
                      ),
                    ),
                    SizedBox(width: 12),
                    if (roomData['extraBed'] ?? false)
                      Expanded(
                        child: _buildSmallInput(
                          label: 'Extra Bed Price (₹)',
                          controller: TextEditingController(
                            text: roomData['extraBedPrice'] ?? '',
                          ),
                          onChanged: (value) =>
                              roomData['extraBedPrice'] = value,
                          hint: '0',
                          keyboardType: TextInputType.number,
                        ),
                      ),
                  ],
