                Text(
                  controller.text.isNotEmpty
                      ? _formatTimeForDisplay(controller.text)
                      : 'Select time',
                  style: TextStyle(
                    fontSize: 14,
                    color: controller.text.isNotEmpty
                        ? _textPrimary
                        : _textSecondary,
                  ),
                ),
