  void _removeDigitalSignature() {
    showDialog(
      context: context,
      builder: (context) => AlertDialog(
        title: Text('Remove Digital Signature'),
        content: Text('Are you sure you want to remove the digital signature?'),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
