                          child: Container(
                            margin: EdgeInsets.symmetric(horizontal: 8),
                            child: Column(
                              children: [
                                Container(
                                  width: 36,
                                  height: 36,
                                  decoration: BoxDecoration(
                                    shape: BoxShape.circle,
                                    color: isActive
                                        ? _primaryColor
                                        : isCompleted
                                        ? _successColor
                                        : Colors.white,
                                    border: Border.all(
                                      color: isActive || isCompleted
                                          ? Colors.transparent
                                          : _borderColor,
                                      width: 2,
                                    ),
                                  ),
                                  child: Center(
                                    child: isCompleted
                                        ? Icon(
                                      Icons.check,
                                      size: 18,
                                      color: Colors.white,
                                    )
