                SizedBox(height: 12),
                Wrap(
                  spacing: 8,
                  runSpacing: 8,
                  children: _selectedRoomTypes.entries.map((entry) {
                    bool isSelected = entry.value;
                    return GestureDetector(
                      onTap: () {
                        setState(() {
                          _selectedRoomTypes[entry.key] = !isSelected;
                        });
                      },
                      child: Container(
                        padding: EdgeInsets.symmetric(
                          horizontal: 14,
                          vertical: 8,
                        ),
                        decoration: BoxDecoration(
                          color: isSelected ? _primaryLight : Colors.white,
                          borderRadius: BorderRadius.circular(20),
                          border: Border.all(
                            color: isSelected ? _primaryColor : _borderColor,
                            width: isSelected ? 2 : 1,
                          ),
                        ),
                        child: Row(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            Icon(
                              isSelected
                                  ? Icons.check_circle
                                  : Icons.circle_outlined,
                              size: 16,
                              color: isSelected
                                  ? _primaryColor
                                  : _textSecondary,
                            ),
                            SizedBox(width: 6),
                            Text(
                              entry.key,
                              style: TextStyle(
                                fontSize: 13,
                                color: isSelected
                                    ? _primaryColor
                                    : _textSecondary,
                                fontWeight: isSelected
                                    ? FontWeight.w600
                                    : FontWeight.w500,
                              ),
                            ),
                          ],
                        ),
                      ),
                    );
                  }).toList(),
                ),
              ],
            ),
            SizedBox(height: 20),

            if (_selectedRoomTypes.entries.any((entry) => entry.value))
              Column(
                children: [
                  Text(
                    'Configure selected room types:',
                    style: TextStyle(
                      fontSize: 14,
                      fontWeight: FontWeight.w600,
                      color: _textPrimary,
                    ),
                  ),
                  SizedBox(height: 16),
                  ..._selectedRoomTypes.entries
                      .where((entry) => entry.value)
                      .map((entry) {
                        String roomType = entry.key;
                        return Container(
                          margin: EdgeInsets.only(bottom: 16),
                          child: _buildRoomConfigurationCard(roomType),
                        );
                      })
                      .toList(),
                ],
              ),

            SizedBox(height: 20),
