  Widget _buildStepContent() {
    switch (_currentStep) {
      case 0:
        return _buildStep1();
      case 1:
        return _buildStep2();
      case 2:
        return _buildStep3();
      case 3:
        return _buildStep4();
      case 4:
        return _buildStep5();
      default:
        return Container();
    }
  }

  Widget _buildStep1() {
    return Column(
      children: [
        _buildCard(
          title: '1. Hotel Identity & Profile',
          children: [
            _buildInputField(
              label: 'Hotel Name',
              controller: _hotelNameController,
              hint: 'Enter 6-star ultra-luxury hotel name',
            ),
            SizedBox(height: 16),

            Container(
              padding: EdgeInsets.all(10),
              decoration: BoxDecoration(
                color: _primaryLight,
