  Widget _buildTimeDropdown({
    required String label,
    required TextEditingController controller,
    required ValueChanged<String> onChanged,
  }) {
    String currentValue = controller.text;
    String displayValue = '';

    if (currentValue.isNotEmpty) {
      for (var option in _timeOptions24Hour) {
        if (option['value'] == currentValue) {
          displayValue = option['value']!;
          break;
        }
      }
    }

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(
          label,
          style: TextStyle(
            fontSize: 13,
            fontWeight: FontWeight.w500,
            color: _textPrimary,
          ),
        ),
        SizedBox(height: 8),
        Container(
          height: 48,
          padding: EdgeInsets.symmetric(horizontal: 12),
          decoration: BoxDecoration(
            border: Border.all(color: _borderColor),
            borderRadius: BorderRadius.circular(8),
          ),
          child: DropdownButtonHideUnderline(
            child: DropdownButton<String>(
              value: displayValue.isNotEmpty ? displayValue : null,
              isExpanded: true,
              icon: Icon(Icons.arrow_drop_down, color: _textSecondary),
              hint: Text('Select time'),
              items: _timeOptions24Hour.map((option) {
                return DropdownMenuItem<String>(
                  value: option['value'],
                  child: Text(option['display']!),
                );
              }).toList(),
              onChanged: (value) {
                if (value != null) {
                  setState(() {
                    controller.text = value;
                  });
                  onChanged(value);
                }
              },
            ),
          ),
        ),
      ],
    );
  }

