  Widget _buildRoyalAccommodationCard(String residenceType) {
    final details = _royalAccommodations[residenceType]!;

    return Container(
      margin: EdgeInsets.only(bottom: 16),
      padding: EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: _primaryLight.withOpacity(0.3),
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: _primaryColor.withOpacity(0.3)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Icon(Icons.settings, size: 18, color: _primaryColor),
              SizedBox(width: 8),
              Text(
                residenceType,
                style: TextStyle(
                  fontSize: 16,
                  fontWeight: FontWeight.w700,
                  color: _primaryColor,
                ),
              ),
            ],
          ),
          SizedBox(height: 16),

          Row(
            children: [
              Expanded(
                child: _buildSmallInput(
                  label: 'Units',
                  controller: TextEditingController(
                    text: _getInitialText(details['units']),
                  ),
                  onChanged: (value) {
                    final intValue = int.tryParse(value) ?? 0;
                    details['units'] = intValue;
                  },
                  hint: '0',
                  keyboardType: TextInputType.number,
                  inputFormatters: [FilteringTextInputFormatter.digitsOnly],
                ),
              ),
              SizedBox(width: 12),
              Expanded(
                child: _buildSmallInput(
                  label: 'Area (sq m)',
                  controller: TextEditingController(
                    text: _getInitialText(details['area']),
                  ),
                  onChanged: (value) => details['area'] = value,
                  hint: '0',
                  keyboardType: TextInputType.number,
                ),
              ),
            ],
          ),
          SizedBox(height: 12),

          Row(
            children: [
              Expanded(
                child: _buildSmallInput(
                  label: 'Max Guests',
                  controller: TextEditingController(
                    text: _getInitialText(details['maxGuests']),
                  ),
                  onChanged: (value) {
                    final intValue = int.tryParse(value) ?? 0;
                    details['maxGuests'] = intValue;
                  },
                  hint: '0',
                  keyboardType: TextInputType.number,
                  inputFormatters: [FilteringTextInputFormatter.digitsOnly],
                ),
              ),
              SizedBox(width: 12),
              Expanded(
                child: _buildSmallInput(
                  label: 'Signature Features',
                  controller: TextEditingController(
                    text: details['signatureFeatures'],
                  ),
                  onChanged: (value) => details['signatureFeatures'] = value,
                  hint: 'Key features',
                ),
              ),
            ],
          ),
          SizedBox(height: 12),

          Row(
            children: [
              Expanded(
                child: _buildSmallInput(
                  label: 'Avg Nightly Rate (USD)',
                  controller: TextEditingController(
                    text: _getInitialText(details['avgNightlyRate']),
                  ),
                  onChanged: (value) {
                    final doubleValue = double.tryParse(value) ?? 0.0;
                    details['avgNightlyRate'] = doubleValue;
                  },
                  hint: '0.00',
                  keyboardType: const TextInputType.numberWithOptions(decimal: true),
                  inputFormatters: [
                    FilteringTextInputFormatter.allow(RegExp(r'^\d+\.?\d{0,2}')),
                  ],
                ),
              ),
              SizedBox(width: 12),
              Expanded(
                child: _buildSmallInput(
                  label: 'Peak Rate (USD)',
                  controller: TextEditingController(
                    text: _getInitialText(details['peakRate']),
                  ),
                  onChanged: (value) {
                    final doubleValue = double.tryParse(value) ?? 0.0;
                    details['peakRate'] = doubleValue;
                  },
                  hint: '0.00',
                  keyboardType: const TextInputType.numberWithOptions(decimal: true),
                  inputFormatters: [
                    FilteringTextInputFormatter.allow(RegExp(r'^\d+\.?\d{0,2}')),
                  ],
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }

