  Widget _buildProfilePhotoUploadItem() {
    final fileName = _profilePhoto['name'] as String? ?? '';
    final isUploaded = (_profilePhoto['uploaded'] as bool?) ?? false;
    final fileSize = (_profilePhoto['size'] as int?) ?? 0;

    Future<void> _pickProfilePhoto() async {
      try {
        FilePickerResult? result = await FilePicker.platform.pickFiles(
          type: FileType.image,
          allowMultiple: false,
        );

        if (result != null && result.files.isNotEmpty) {
          final file = result.files.first;

          if (file.size > 2 * 1024 * 1024) {
            _showErrorDialog(
              'File too large',
              'Please select a profile photo smaller than 2MB',
            );
            return;
          }

          setState(() {
            _profilePhoto['name'] = file.name;
            _profilePhoto['size'] = file.size;
            _profilePhoto['path'] = file.path ?? '';
            _profilePhoto['uploaded'] = true;
          });

          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text('Profile photo uploaded successfully'),
              backgroundColor: _successColor,
              duration: Duration(seconds: 2),
            ),
          );
        }
      } catch (e) {
        _showErrorDialog(
          'Upload Error',
          'Failed to upload profile photo: ${e.toString()}',
        );
      }
    }

    void _viewProfilePhoto() {
      if (fileName.isNotEmpty) {
        showDialog(
          context: context,
          builder: (context) => AlertDialog(
            title: const Text('Profile Photo'),
            content: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Container(
                  width: 200,
                  height: 200,
                  decoration: BoxDecoration(
                    color: Colors.grey[100],
                    borderRadius: BorderRadius.circular(8),
                    border: Border.all(color: Colors.grey[300]!),
                  ),
                  child: Center(
                    child: Icon(
                      Icons.person,
                      size: 80,
                      color: Colors.grey[400],
                    ),
                  ),
                ),
                SizedBox(height: 16),
                Text('File: $fileName'),
                Text('Size: ${(fileSize / 1024).toStringAsFixed(1)} KB'),
              ],
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(context),
                child: const Text('Close'),
              ),
            ],
          ),
        );
      }
    }

    void _removeProfilePhoto() {
      showDialog(
        context: context,
        builder: (context) => AlertDialog(
          title: const Text('Remove Profile Photo'),
          content: const Text('Are you sure you want to remove this profile photo?'),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(context),
              child: const Text('Cancel'),
            ),
            TextButton(
              onPressed: () {
                setState(() {
                  _profilePhoto['name'] = '';
                  _profilePhoto['size'] = 0;
                  _profilePhoto['path'] = '';
                  _profilePhoto['uploaded'] = false;
                });
                Navigator.pop(context);
                ScaffoldMessenger.of(context).showSnackBar(
                  SnackBar(
                    content: const Text('Profile photo removed'),
                    backgroundColor: Colors.orange,
                    duration: Duration(seconds: 2),
                  ),
                );
              },
              child: const Text('Remove', style: TextStyle(color: Colors.red)),
            ),
          ],
        ),
      );
    }

    return Container(
      margin: EdgeInsets.only(bottom: 12),
      padding: EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: isUploaded ? _successColor.withOpacity(0.05) : Colors.white,
        borderRadius: BorderRadius.circular(8),
        border: Border.all(
          color: isUploaded ? _successColor : _borderColor,
          width: isUploaded ? 1.5 : 1,
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Row(
                children: [
                  Icon(
                    Icons.person,
                    size: 20,
                    color: isUploaded ? _successColor : _primaryColor,
                  ),
                  SizedBox(width: 10),
                  Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        'Profile Photo',
                        style: TextStyle(
                          fontWeight: FontWeight.w600,
                          fontSize: 14,
                          color: isUploaded ? _successColor : _textPrimary,
                        ),
                      ),
                      Text(
                        'JPG, PNG format (Max 2MB)',
                        style: TextStyle(fontSize: 11, color: _textSecondary),
                      ),
                    ],
                  ),
                ],
              ),
              if (isUploaded)
                Row(
                  children: [
                    Icon(Icons.check_circle, color: _successColor, size: 16),
                    SizedBox(width: 4),
                    Text(
                      'Uploaded',
                      style: TextStyle(
                        fontSize: 11,
                        color: _successColor,
                        fontWeight: FontWeight.w500,
                      ),
                    ),
                  ],
                ),
            ],
          ),
          SizedBox(height: 12),

          if (!isUploaded)
            SizedBox(
              width: double.infinity,
              child: ElevatedButton.icon(
                onPressed: _pickProfilePhoto,
                style: ElevatedButton.styleFrom(
                  backgroundColor: _primaryColor,
                  padding: EdgeInsets.symmetric(vertical: 14, horizontal: 7),
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(8),
                  ),
                ),
                icon: Icon(Icons.upload, size: 18, color: Colors.white),
                label: Text(
                  'Upload Profile Photo',
                  style: TextStyle(
                    fontSize: 14,
                    fontWeight: FontWeight.w500,
                    color: Colors.white,
                  ),
                ),
              ),
            ),

          if (isUploaded && fileName.isNotEmpty)
            Container(
              padding: EdgeInsets.all(12),
              decoration: BoxDecoration(
                color: _primaryLight,
                borderRadius: BorderRadius.circular(8),
              ),
              child: Row(
                children: [
                  Container(
                    width: 50,
                    height: 50,
                    decoration: BoxDecoration(
                      color: _primaryColor.withOpacity(0.1),
                      borderRadius: BorderRadius.circular(8),
                      border: Border.all(color: _primaryColor.withOpacity(0.3)),
                    ),
                    child: Center(
                      child: Icon(
                        Icons.person,
                        size: 30,
                        color: _primaryColor,
                      ),
                    ),
                  ),
                  SizedBox(width: 12),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          fileName,
                          style: TextStyle(
                            fontWeight: FontWeight.w500,
                            fontSize: 13,
                            color: _textPrimary,
                          ),
                          overflow: TextOverflow.ellipsis,
                          maxLines: 1,
                        ),
                        SizedBox(height: 4),
                        Text(
                          '${(fileSize / 1024).toStringAsFixed(1)} KB',
                          style: TextStyle(fontSize: 11, color: _textSecondary),
                        ),
                      ],
                    ),
                  ),
                  SizedBox(width: 8),
                  Row(
                    children: [
                      IconButton(
                        onPressed: _viewProfilePhoto,
                        icon: Icon(
                          Icons.remove_red_eye,
                          size: 20,
                          color: _primaryColor,
                        ),
                        tooltip: 'Preview',
                      ),
                      IconButton(
                        onPressed: _removeProfilePhoto,
                        icon: Icon(Icons.delete, size: 20, color: Colors.red),
                        tooltip: 'Remove',
                      ),
                    ],
                  ),
                ],
              ),
            ),
        ],
      ),
    );
  }


