class GooglePayService {
  static const String merchantUpiId = 'sabarisoftware25@okhdfcbank';

  static Future<bool> openGooglePay({
    required String amount,
    required String orderId,
  }) async {
    try {
      String formattedAmount = amount.replaceAll(',', '');

      final String upiUrl =
          'upi://pay?pa=$merchantUpiId'
          '&pn=Hotel%20Registration'
          '&am=$formattedAmount'
          '&tr=$orderId'
          '&tn=Hotel%20Registration%20Fee'
          '&cu=INR';

      print('Opening UPI: $upiUrl');

      final Uri uri = Uri.parse(upiUrl);

      if (await canLaunchUrl(uri)) {
        await launchUrl(uri, mode: LaunchMode.externalApplication);
        return true;
      }

      return false;
    } catch (e) {
      print('Error opening Google Pay: $e');
      return false;
    }
  }
}

class PaymentMethodScreen extends StatefulWidget {
  final Map<String, dynamic> registrationData;
  final String hotelCategory;
  final bool declarationAccepted;

  const PaymentMethodScreen({
    Key? key,
    required this.registrationData,
    required this.hotelCategory,
    required this.declarationAccepted,
  }) : super(key: key);

  @override
  State<PaymentMethodScreen> createState() => _PaymentMethodScreenState();
}

class _PaymentMethodScreenState extends State<PaymentMethodScreen> {
  final Color _primaryColor = Color(0xFFFF5F6D);
  final Color _successColor = Color(0xFF10B981);
  final Color _textDark = Color(0xFF111827);
  final Color _textLight = Color(0xFF6B7280);
  final Color _borderColor = Color(0xFFE5E7EB);

  bool _isLoading = false;

  double get _paymentAmount {
    switch (widget.hotelCategory) {
      case '2-Star':
      case '3-Star':
      case '4-Star':
      case '5-Star':
      case '6-Star':
        return 1.00;
      case 'Normal':
      default:
        return 1.00;
    }
  }

  double get _totalAmount {
    return _paymentAmount;
  }

  String get _orderId {
    return 'HOTEL${DateTime.now().millisecondsSinceEpoch}';
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.white,
      appBar: AppBar(
        backgroundColor: Colors.white,
        elevation: 0,
        leading: IconButton(
          icon: Icon(Icons.arrow_back, color: _textDark),
          onPressed: () => Navigator.pop(context),
        ),
        title: Text(
          'Payment for Registration',
          style: TextStyle(
            fontSize: 18,
            fontWeight: FontWeight.w600,
            color: _textDark,
          ),
        ),
        centerTitle: true,
      ),
      body: SingleChildScrollView(
        padding: EdgeInsets.all(16),
        child: Column(
          children: [
            SizedBox(height: 20),
            _buildPaymentDetailsCard(),
            SizedBox(height: 30),
            _buildGooglePayButton(),
            SizedBox(height: 20),
            _buildTermsText(),
          ],
        ),
      ),
    );
  }

  Widget _buildPaymentDetailsCard() {
    return Container(
      padding: EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: _borderColor),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            'Payment Summary',
            style: TextStyle(
              fontSize: 16,
              fontWeight: FontWeight.w600,
              color: _textDark,
            ),
          ),
          Divider(height: 20, color: _borderColor),

          _buildRow(
            'Registration Fee',
            '₹${_paymentAmount.toStringAsFixed(2)}',
          ),
          SizedBox(height: 8),

          _buildRow('Platform Charges', '₹0.00'),

          Divider(height: 20, color: _borderColor),

          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Text(
                'Total Amount',
                style: TextStyle(
                  fontSize: 16,
                  fontWeight: FontWeight.w700,
                  color: _textDark,
                ),
              ),
              Text(
                '₹${_totalAmount.toStringAsFixed(2)}',
                style: TextStyle(
                  fontSize: 20,
                  fontWeight: FontWeight.w800,
                  color: _primaryColor,
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }

  Widget _buildRow(String label, String amount) {
    return Row(
      mainAxisAlignment: MainAxisAlignment.spaceBetween,
      children: [
        Text(label, style: TextStyle(color: _textLight)),
        Text(amount, style: TextStyle(fontWeight: FontWeight.w600)),
      ],
    );
  }

  Widget _buildGooglePayButton() {
    return Container(
      width: double.infinity,
      height: 55,
      decoration: BoxDecoration(
        gradient: LinearGradient(
          colors: [_primaryColor, _primaryColor.withOpacity(0.8)],
          begin: Alignment.topLeft,
          end: Alignment.bottomRight,
        ),
        borderRadius: BorderRadius.circular(12),
        boxShadow: [
          BoxShadow(
            color: _primaryColor.withOpacity(0.3),
            blurRadius: 8,
            offset: Offset(0, 4),
          ),
        ],
      ),
      child: ElevatedButton(
        style: ElevatedButton.styleFrom(
          backgroundColor: Colors.transparent,
          shadowColor: Colors.transparent,
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(12),
          ),
        ),
        onPressed: _isLoading ? null : _processPayment,

        child: _isLoading
            ? SizedBox(
                height: 20,
                width: 20,
                child: CircularProgressIndicator(
                  strokeWidth: 2,
                  color: Colors.white,
                ),
              )
            : Row(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  Icon(Icons.payment, color: Colors.white, size: 20),
                  SizedBox(width: 8),
                  Text(
                    'Pay with Google Pay',
                    style: TextStyle(
                      color: Colors.white,
                      fontSize: 16,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                ],
              ),
      ),
    );
  }

  Widget _buildTermsText() {
    return Text(
      'You will be redirected to Google Pay to complete the payment',
      textAlign: TextAlign.center,
      style: TextStyle(fontSize: 12, color: _textLight),
    );
  }

  Future<void> _processPayment() async {
    setState(() {
      _isLoading = true;
    });

    try {
      final opened = await GooglePayService.openGooglePay(
        amount: _totalAmount.toStringAsFixed(2),
        orderId: _orderId,
      );

      if (opened) {
        setState(() {
          _isLoading = false;
        });

      } else {
        setState(() {
          _isLoading = false;
        });

        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('Could not open Google Pay'),
            backgroundColor: Colors.red,
          ),
        );
      }
    } catch (e) {
      setState(() {
        _isLoading = false;
      });

      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('Error: ${e.toString()}'),
          backgroundColor: Colors.red,
        ),
      );
    }
  }

  void _showPaymentInstructions() {
    showDialog(
      context: context,
      builder: (context) => AlertDialog(
        title: Text('Payment Instructions'),
        content: Column(
          mainAxisSize: MainAxisSize.min,
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text('1. Complete payment in Google Pay'),
            Text('2. If you see "Bank Limit Exceeded":'),
            Text('   • Try tomorrow (limits reset)'),
            Text('   • Use different bank account'),
            Text('   • Check with your bank'),
            Text('3. Return here after payment'),
          ],
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: Text('OK'),
          ),
        ],
      ),
    );
  }

  void _checkPaymentStatus() {
    showDialog(
      context: context,
      barrierDismissible: false,
      builder: (context) => AlertDialog(
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(16)),
        title: Column(
          children: [
            Icon(Icons.check_circle, color: _successColor, size: 60),
            SizedBox(height: 12),
            Text(
              'Payment Successful!',
              style: TextStyle(
                fontSize: 18,
                fontWeight: FontWeight.w700,
                color: _textDark,
              ),
            ),
          ],
        ),
        content: Text(
          'Your payment has been processed successfully.',
          textAlign: TextAlign.center,
          style: TextStyle(color: _textLight),
        ),
        actions: [
          Center(
            child: CircularProgressIndicator(
              valueColor: AlwaysStoppedAnimation<Color>(_primaryColor),
            ),
          ),
          SizedBox(height: 16),
        ],
      ),
    );

    Future.delayed(Duration(seconds: 2), () {
      Navigator.pop(context);
      Navigator.pushReplacement(
        context,
        MaterialPageRoute(
          builder: (context) => RegistrationSummaryScreen(
            registrationData: widget.registrationData,
            hotelCategory: widget.hotelCategory,
            declarationAccepted: widget.declarationAccepted,
          ),
        ),
      );
    });
  }
}

