  Future<void> _pickOwnerPhoto() async {
    print("_pickOwnerPhoto called");
    try {

      FilePickerResult? result = await FilePicker.platform.pickFiles(
        type: FileType.custom, // Changed from FileType.image
        allowedExtensions: [
          'jpg',
          'jpeg',
          'png',
        ], // This only works with FileType.custom
        allowMultiple: false,
      );

      if (result != null && result.files.isNotEmpty) {
        print("File selected: ${result.files.first.name}");
        final file = result.files.first;

        if (file.size > 5 * 1024 * 1024) {
          _showErrorDialog(
            'File too large',
            'Please select a photo smaller than 5MB',
          );
          return;
        }

        setState(() {
          _ownerPhotoInfo = {
            'name': file.name,
            'size': file.size,
            'path': file.path ?? '',
            'uploaded': true,
          };
          print("Photo info updated: ${_ownerPhotoInfo}");
        });

        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('Photo uploaded successfully'),
            backgroundColor: _successColor,
            duration: Duration(seconds: 2),
          ),
        );
      } else {
        print("No file selected");
      }
    } catch (e) {
      print("Error in _pickOwnerPhoto: $e");
      _showErrorDialog(
        'Upload Error',
        'Failed to upload photo: ${e.toString()}',
      );
    }
  }

