  Future<void> _pickFile(String fileType) async {
    try {
      FilePickerResult? result = await FilePicker.platform.pickFiles(
        type: FileType.custom,
        allowedExtensions: ['jpg', 'jpeg', 'png', 'pdf', 'doc', 'docx'],
        allowMultiple: false,
      );

      if (result != null && result.files.isNotEmpty) {
        final file = result.files.first;

        setState(() {
          switch (fileType) {
            case 'ownership':
              _ownershipProofInfo = {
                'name': file.name,
                'size': file.size,
                'path': file.path ?? '',
                'uploaded': true,
              };
              break;
            case 'cancellation':
              _cancellationPolicyInfo = {
                'name': file.name,
                'size': file.size,
                'path': file.path ?? '',
                'uploaded': true,
              };
              break;
            case 'idproof':
              _idProofInfo = {
                'name': file.name,
                'size': file.size,
                'path': file.path ?? '',
                'uploaded': true,
              };
              break;
            case 'calendar':
              _availabilityCalendarInfo = {
                'name': file.name,
                'size': file.size,
                'path': file.path ?? '',
                'uploaded': true,
              };
              break;
            case 'cheque':
              _cancelledChequeInfo = {
                'name': file.name,
                'size': file.size,
                'path': file.path ?? '',
                'uploaded': true,
              };
              break;
          }
        });

        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('File uploaded successfully'),
            backgroundColor: _successColor,
            duration: Duration(seconds: 2),
          ),
        );
      }
    } catch (e) {
      _showErrorDialog(
        'Upload Error',
        'Failed to upload file: ${e.toString()}',
      );
    }
  }

