  Widget _buildBHKDetailsCard(String bhkType) {

    if (!_selectedSubOptionsDetails.containsKey(bhkType)) {
      _selectedSubOptionsDetails[bhkType] = BHKDetails(type: bhkType);
    }

    final bhk = _selectedSubOptionsDetails[bhkType]!;

    return Container(
      margin: EdgeInsets.only(bottom: 16),
      padding: EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: _primaryLight.withOpacity(0.3),
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: _primaryColor.withOpacity(0.3)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Text(
                '$bhkType Details',
                style: TextStyle(
                  fontSize: 16,
                  fontWeight: FontWeight.bold,
                  color: _primaryColor,
                ),
              ),
              IconButton(
                onPressed: () {
                  setState(() {
                    _selectedSubOptions.remove(bhkType);
                    _selectedSubOptionsDetails.remove(bhkType);
                  });
                },
                icon: Icon(Icons.close, color: Colors.red, size: 20),
              ),
            ],
          ),
          SizedBox(height: 12),
          Row(
            children: [
              Expanded(
                child: _buildBHKInputField(
                  label: 'Total Number of Units *',
                  value: bhk.totalUnits,
                  hint: 'Enter number',
                  keyboardType: TextInputType.number,
                  onChanged: (value) {
                    setState(() {
                      bhk.totalUnits = value;
                    });
                  },
                ),
              ),
              SizedBox(width: 16),
              Expanded(
                child: _buildBHKInputField(
                  label: 'Total Bedrooms *',
                  value: bhk.totalBedrooms,
                  hint: 'Enter number',
                  keyboardType: TextInputType.number,
                  onChanged: (value) {
                    setState(() {
                      bhk.totalBedrooms = value;
                    });
                  },
                ),
              ),
            ],
          ),
          SizedBox(height: 16),
          Row(
            children: [
              Expanded(
                child: _buildBHKInputField(
                  label: 'Total Bathrooms *',
                  value: bhk.totalBathrooms,
                  hint: 'Enter number',
                  keyboardType: TextInputType.number,
                  onChanged: (value) {
                    setState(() {
                      bhk.totalBathrooms = value;
                    });
                  },
                ),
              ),
              SizedBox(width: 16),
              Expanded(
                child: _buildBHKInputField(
                  label: 'Max Guest Capacity *',
                  value: bhk.guestCapacity,
                  hint: 'Enter number',
                  keyboardType: TextInputType.number,
                  onChanged: (value) {
                    setState(() {
                      bhk.guestCapacity = value;
                    });
                  },
                ),
              ),
            ],
          ),
          SizedBox(height: 16),
          Row(
            children: [
              Expanded(
                child: _buildBHKInputField(
                  label: 'Floor Number',
                  value: bhk.floorNumber,
                  hint: 'Enter floor',
                  keyboardType: TextInputType.number,
                  onChanged: (value) {
                    setState(() {
                      bhk.floorNumber = value;
                    });
                  },
                ),
              ),
              SizedBox(width: 16),
              Expanded(
                child: _buildBHKInputField(
                  label: 'Total Floors in Building',
                  value: bhk.totalFloors,
                  hint: 'Enter total floors',
                  keyboardType: TextInputType.number,
                  onChanged: (value) {
                    setState(() {
                      bhk.totalFloors = value;
                    });
                  },
                ),
              ),
            ],
          ),
          SizedBox(height: 16),
          Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                'Elevator Available',
                style: TextStyle(
                  fontSize: 13,
                  fontWeight: FontWeight.w500,
                  color: _textPrimary,
                ),
              ),
              SizedBox(height: 8),
              Row(
                children: [
                  Expanded(
                    child: RadioListTile<String>(
                      title: Text('Yes'),
                      value: 'Yes',
                      groupValue: bhk.elevatorAvailable,
                      onChanged: (value) {
                        setState(() {
                          bhk.elevatorAvailable = value ?? '';
                        });
                      },
                      activeColor: _primaryColor,
                      dense: true,
                      contentPadding: EdgeInsets.zero,
                    ),
                  ),
                  Expanded(
                    child: RadioListTile<String>(
                      title: Text('No'),
                      value: 'No',
                      groupValue: bhk.elevatorAvailable,
                      onChanged: (value) {
                        setState(() {
                          bhk.elevatorAvailable = value ?? '';
                        });
                      },
                      activeColor: _primaryColor,
                      dense: true,
                      contentPadding: EdgeInsets.zero,
                    ),
                  ),
                ],
              ),
            ],
          ),
          SizedBox(height: 16),
          Row(
            children: [
              Expanded(
                child: _buildBHKInputField(
                  label: 'Property Size (Sq. Ft.)',
                  value: bhk.propertySize,
                  hint: 'Enter size',
                  keyboardType: TextInputType.number,
                  onChanged: (value) {
                    setState(() {
                      bhk.propertySize = value;
                    });
                  },
                ),
              ),
            ],
          ),
          SizedBox(height: 16),
          _buildBHKInputField(
            label: 'Property Description',
            value: bhk.propertyDescription,
            hint: 'Describe this $bhkType unit',
            maxLines: 3,
            onChanged: (value) {
              setState(() {
                bhk.propertyDescription = value;
              });
            },
          ),
        ],
      ),
    );
  }

  Widget _buildBHKInputField({
    required String label,
    required String value,
    required String hint,
    TextInputType? keyboardType,
    int maxLines = 1,
    required Function(String) onChanged,
  }) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(
          label,
          style: TextStyle(
            fontSize: 12,
            fontWeight: FontWeight.w500,
            color: _textSecondary,
          ),
        ),
        SizedBox(height: 4),
        TextFormField(
          initialValue: value,
          keyboardType: keyboardType,
          maxLines: maxLines,
          onChanged: onChanged,
          decoration: InputDecoration(
            hintText: hint,
            contentPadding: EdgeInsets.symmetric(horizontal: 12, vertical: 10),
            border: OutlineInputBorder(
              borderRadius: BorderRadius.circular(8),
              borderSide: BorderSide(color: _borderColor),
            ),
            enabledBorder: OutlineInputBorder(
              borderRadius: BorderRadius.circular(8),
              borderSide: BorderSide(color: _borderColor),
            ),
            focusedBorder: OutlineInputBorder(
              borderRadius: BorderRadius.circular(8),
              borderSide: BorderSide(color: _primaryColor),
            ),
          ),
        ),
      ],
    );
  }

  Widget _buildBHKOptionsSection() {
    final bhkOptions = _propertyTypes.firstWhere(
          (type) => type['title'] == _selectedPropertyType,
      orElse: () => {'bhkOptions': []},
    )['bhkOptions'] as List<String>;

    if (bhkOptions.isEmpty) return SizedBox.shrink();

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(
          'Select BHK Types Available',
          style: TextStyle(
            fontSize: 14,
            fontWeight: FontWeight.w600,
            color: _textPrimary,
          ),
        ),
        SizedBox(height: 8),
        Text(
          'You can select multiple BHK types for this property',
          style: TextStyle(fontSize: 12, color: _textSecondary),
        ),
        SizedBox(height: 12),
        Wrap(
          spacing: 12,
          runSpacing: 12,
          children: bhkOptions.map((bhkType) {
            bool isSelected = _selectedBHKs.any((b) => b.type == bhkType);
            return GestureDetector(
              onTap: () {
                setState(() {
                  if (isSelected) {
                    // Remove BHK
                    _selectedBHKs.removeWhere((b) => b.type == bhkType);
                    _bhkControllers.remove(bhkType);
                  } else {
                    // Add new BHK
                    _selectedBHKs.add(BHKDetails(type: bhkType));
                    _initializeBHKControllers(bhkType);
                  }
                });
              },
              child: Container(
                padding: EdgeInsets.symmetric(horizontal: 16, vertical: 10),
                decoration: BoxDecoration(
                  color: isSelected ? _primaryColor : Colors.white,
                  borderRadius: BorderRadius.circular(12),
                  border: Border.all(
                    color: isSelected ? _primaryColor : _borderColor,
                    width: 1.5,
                  ),
                ),
                child: Text(
                  bhkType,
                  style: TextStyle(
                    fontSize: 14,
                    fontWeight: FontWeight.w600,
                    color: isSelected ? Colors.white : _textPrimary,
                  ),
                ),
              ),
            );
          }).toList(),
        ),
        if (_selectedBHKs.isNotEmpty)
          Padding(
            padding: EdgeInsets.only(top: 12),
            child: Text(
              'Selected: ${_selectedBHKs.map((b) => b.type).join(", ")}',
              style: TextStyle(fontSize: 12, color: _primaryColor),
            ),
          ),
        SizedBox(height: 16),
        Divider(color: _borderColor),
        SizedBox(height: 16),
      ],
    );
  }

