  Future<void> _pickMedia(String mediaKey, bool allowMultiple) async {
    try {
      FilePickerResult? result = await FilePicker.platform.pickFiles(
        type: FileType.media,
        allowMultiple: allowMultiple,
      );

      if (result != null && result.files.isNotEmpty) {
        setState(() {
          for (var file in result.files) {
            _mediaFiles[mediaKey]!.add({
              'name': file.name,
              'size': file.size,
              'path': file.path ?? '',
              'uploaded': true,
            });
          }
        });

        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('${result.files.length} file(s) uploaded'),
            backgroundColor: _successColor,
            duration: Duration(seconds: 2),
          ),
        );
      }
    } catch (e) {
      _showErrorDialog(
        'Upload Error',
        'Failed to upload files: ${e.toString()}',
      );
    }
  }

  void _viewMediaFile(Map<String, dynamic> file) {
    if (file['path'] != null && file['path'].isNotEmpty) {
      showDialog(
        context: context,
