  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: _bgColor,

      appBar: AppBar(
        backgroundColor: Colors.white,
        elevation: 0,
        leading: IconButton(
          icon: Icon(Icons.arrow_back, color: _textPrimary),
          onPressed: () => Navigator.pop(context),
        ),
        title: Text(
          'Resort Registration Vendor Form',
          style: TextStyle(
            fontSize: 19,
            fontWeight: FontWeight.w600,
            color: _textPrimary,
          ),
        ),
        centerTitle: true,
      ),
      body: Form(
        key: _formKey,
        child: Column(
          children: [
            _buildProgressIndicator(),
            Expanded(
              child: SingleChildScrollView(
                padding: EdgeInsets.all(16),
                child: _buildStepContent(),
              ),
            ),
            _buildNavigationButtons(),
          ],
        ),
      ),
    );
  }

  Widget _buildProgressIndicator() {
    return Container(
      padding: EdgeInsets.all(5),
      color: Colors.white,
      child: Column(
        children: [
          SingleChildScrollView(
            scrollDirection: Axis.horizontal,
            child: Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: List.generate(_steps.length, (index) {
                bool isActive = index == _currentStep;
                bool isCompleted = index < _currentStep;

                return Container(
                  margin: EdgeInsets.symmetric(horizontal: 2),
                  child: GestureDetector(
                    onTap: () {
                      if (index <= _currentStep) {
                        setState(() {
                          _currentStep = index;
                        });
                      }
                    },
                    child: Column(
                      children: [
                        Container(
                          width: 32,
                          height: 32,
                          decoration: BoxDecoration(
                            shape: BoxShape.circle,
                            color: isActive
                                ? _primaryColor
                                : isCompleted
                                ? _successColor
                                : Colors.white,
                            border: Border.all(
                              color: isActive || isCompleted
                                  ? Colors.transparent
                                  : _borderColor,
                              width: 2,
                            ),
                          ),
                          child: Center(
                            child: isCompleted
                                ? Icon(
                                    Icons.check,
                                    size: 18,
                                    color: Colors.white,
                                  )
                                : Text(
                                    '${index + 1}',
                                    style: TextStyle(
                                      color: isActive || isCompleted
                                          ? Colors.white
                                          : _textSecondary,
                                      fontWeight: FontWeight.w600,
                                      fontSize: 14,
                                    ),
                                  ),
                          ),
                        ),
                        SizedBox(height: 8),
                        SizedBox(
                          width: 70,
                          child: Text(
                            _steps[index]['title'],
                            style: TextStyle(
                              fontSize: 11,
                              fontWeight: FontWeight.w500,
                              color: isActive || isCompleted
                                  ? _textPrimary
                                  : _textSecondary,
                            ),
                            textAlign: TextAlign.center,
                            maxLines: 2,
                            overflow: TextOverflow.ellipsis,
                          ),
                        ),
                      ],
                    ),
                  ),
                );
              }),
            ),
          ),
          SizedBox(height: 16),
          LinearProgressIndicator(
            value: (_currentStep + 1) / _steps.length,
            backgroundColor: _borderColor,
            color: _primaryColor,
            minHeight: 4,
            borderRadius: BorderRadius.circular(2),
          ),
          SizedBox(height: 8),
          Row(
            mainAxisAlignment: MainAxisAlignment.spaceBetween,
            children: [
              Text(
                'Step ${_currentStep + 1} of ${_steps.length}',
                style: TextStyle(fontSize: 12, color: _textSecondary),
              ),
              Text(
                '${((_currentStep + 1) / _steps.length * 100).toInt()}%',
                style: TextStyle(
                  fontSize: 12,
                  fontWeight: FontWeight.w600,
                  color: _primaryColor,
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }

  Widget _buildStepContent() {
    switch (_currentStep) {
      case 0:
        return _buildBasicInfoStep();
      case 1:
        return _buildLocationPropertyStep();
      case 2:
        return _buildAmenitiesPricingStep();
      case 3:
        return _buildLegalBankStep();
      case 4:
        return _buildMediaTermsStep();
      default:
        return Container();
    }
  }

  Widget _buildBasicInfoStep() {
    return Column(
      children: [
        _buildCard(
          title: 'Basic Information',
          children: [
            _buildInputField(
              label: 'Resort Name',
              controller: _resortNameController,
              hint: 'Enter resort name',
            ),
            SizedBox(height: 16),
            Row(
              children: [
                Expanded(
                  child: _buildInputField(
                    label: 'Owner / General Manager Name',
                    controller: _ownerNameController,
                    hint: 'Enter owner/GM name',
                  ),
                ),
                SizedBox(width: 16),
                Expanded(
                  child: _buildInputField(
                    label: 'Contact Person Name',
                    controller: _contactPersonController,
                    hint: 'Enter contact person',
                  ),
                ),
              ],
            ),
            SizedBox(height: 16),
            Row(
              children: [
                Expanded(
                  child: _buildInputField(
                    label: 'Mobile Number',
                    controller: _mobileController,
                    hint: 'Enter mobile number',
                    keyboardType: TextInputType.phone,
                  ),
                ),
                SizedBox(width: 16),
                Expanded(
                  child: _buildInputField(
                    label: 'Alternate Mobile',
                    controller: _altMobileController,
                    hint: 'Optional',
                    keyboardType: TextInputType.phone,
                  ),
                ),
              ],
            ),
            SizedBox(height: 16),
            Row(
              children: [
                Expanded(
                  child: _buildInputField(
                    label: 'Email Address',
                    controller: _emailController,
                    hint: 'example@email.com',
                    keyboardType: TextInputType.emailAddress,
                  ),
                ),
                SizedBox(width: 16),
                Expanded(
                  child: _buildInputField(
                    label: 'Website',
                    controller: _websiteController,
                    hint: 'https://example.com',
                  ),
                ),
              ],
            ),
            SizedBox(height: 16),
            _buildInputField(
              label: 'Company Name',
              controller: _companyNameController,
              hint: 'Enter company name',
            ),
            SizedBox(height: 16),
            _buildPhotoUploadItem(
              label: 'Profile Photo',
              fileInfo: _ownerPhotoInfo,
              onUpload: _pickOwnerPhoto,
              onView: _viewOwnerPhoto,
              onRemove: _removeOwnerPhoto,
            ),
          ],
        ),
      ],
    );
  }



