  Widget _buildCustomAmenitiesSection() {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(
          'Other Amenities',
          style: TextStyle(
            fontSize: 13,
            fontWeight: FontWeight.w600,
            color: _textPrimary,
          ),
        ),
        SizedBox(height: 4),
        Text(
          'Add any additional amenities',
          style: TextStyle(fontSize: 12, color: _textSecondary),
        ),
        SizedBox(height: 8),
        Row(
          children: [
            Expanded(
              child: TextFormField(
                controller: _otherAmenityController,
                decoration: InputDecoration(
                  hintText: 'Enter amenity...',
                  contentPadding: EdgeInsets.symmetric(
                    horizontal: 12,
                    vertical: 12,
                  ),
                  border: OutlineInputBorder(
                    borderRadius: BorderRadius.circular(8),
                    borderSide: BorderSide(color: _borderColor),
                  ),
                ),
                onFieldSubmitted: (value) {
                  if (value.trim().isNotEmpty) {
                    _addCustomAmenity();
                  }
                },
              ),
            ),
            SizedBox(width: 8),
            SizedBox(
              height: 48,
              child: ElevatedButton(
                onPressed: _addCustomAmenity,
                style: ElevatedButton.styleFrom(
                  backgroundColor: _primaryColor,
                  shape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(8),
                  ),
                  padding: EdgeInsets.symmetric(horizontal: 16),
                ),
                child: Text('Add', style: TextStyle(color: Colors.white)),
              ),
            ),
          ],
        ),
        if (_customAmenities.isNotEmpty)
          Padding(
            padding: EdgeInsets.only(top: 12),
            child: Wrap(
              spacing: 8,
              runSpacing: 8,
              children: _customAmenities.map((amenity) {
                return Container(
                  padding: EdgeInsets.symmetric(horizontal: 12, vertical: 6),
                  decoration: BoxDecoration(
                    color: _primaryLight,
                    borderRadius: BorderRadius.circular(16),
                    border: Border.all(color: _primaryColor),
                  ),
                  child: Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Text(
                        amenity,
                        style: TextStyle(fontSize: 12, color: _primaryColor),
                      ),
                      SizedBox(width: 4),
                      GestureDetector(
                        onTap: () => _removeCustomAmenity(amenity),
                        child: Icon(
                          Icons.close,
                          size: 14,
                          color: _primaryColor,
                        ),
                      ),
                    ],
                  ),
                );
              }).toList(),
            ),
          ),
      ],
    );
  }

