  Widget _getFileIcon(String fileName) {
    final ext = fileName.split('.').last.toLowerCase();

    if (['jpg', 'jpeg', 'png', 'gif', 'bmp'].contains(ext)) {
      return Icon(Icons.image, size: 20, color: _primaryColor);
    } else if (['pdf'].contains(ext)) {
      return Icon(Icons.picture_as_pdf, size: 20, color: Colors.red);
    } else if (['doc', 'docx'].contains(ext)) {
      return Icon(Icons.description, size: 20, color: Colors.blue);
    } else if (['mp4', 'mov', 'avi'].contains(ext)) {
      return Icon(Icons.video_file, size: 20, color: Colors.purple);
    } else {
      return Icon(Icons.insert_drive_file, size: 20, color: _primaryColor);
    }
  }

  Color _getFileIconColor(String fileName) {
    final ext = fileName.split('.').last.toLowerCase();

    if (['jpg', 'jpeg', 'png', 'gif', 'bmp'].contains(ext)) {
      return _primaryColor.withOpacity(0.1);
    } else if (['pdf'].contains(ext)) {
      return Colors.red.withOpacity(0.1);
    } else if (['doc', 'docx'].contains(ext)) {
      return Colors.blue.withOpacity(0.1);
    } else if (['mp4', 'mov', 'avi'].contains(ext)) {
      return Colors.purple.withOpacity(0.1);
    } else {
      return _primaryColor.withOpacity(0.1);
    }
  }

  void _addCustomAmenity() {
    final amenity = _otherAmenityController.text.trim();
    if (amenity.isNotEmpty && !_customAmenities.contains(amenity)) {
      setState(() {
        _customAmenities.add(amenity);
        _otherAmenityController.clear();
      });
    }
  }

  void _removeCustomAmenity(String amenity) {
    setState(() {
      _customAmenities.remove(amenity);
    });
  }

  Future<void> _pickOwnerPhoto() async {
    try {
      FilePickerResult? result = await FilePicker.platform.pickFiles(
        type: FileType.custom,
        allowedExtensions: ['jpg', 'jpeg', 'png'],
        allowMultiple: false,
      );

      if (result != null && result.files.isNotEmpty) {
        final file = result.files.first;

        if (file.size > 5 * 1024 * 1024) {
          _showErrorDialog(
            'File too large',
            'Please select a photo smaller than 5MB',
          );
          return;
        }

        setState(() {
          _ownerPhotoInfo = {
            'name': file.name,
            'size': file.size,
            'path': file.path ?? '',
            'uploaded': true,
          };
        });

        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('Photo uploaded successfully'),
            backgroundColor: _successColor,
            duration: Duration(seconds: 2),
          ),
        );
      }
    } catch (e) {
      _showErrorDialog(
        'Upload Error',
        'Failed to upload photo: ${e.toString()}',
      );
    }
  }

  void _viewOwnerPhoto() {
    if (_ownerPhotoInfo['path'] != null && _ownerPhotoInfo['path'].isNotEmpty) {
      showDialog(
        context: context,
        builder: (context) => AlertDialog(
          title: Text('Profile Photo'),
          content: Container(
            width: 200,
            height: 200,
            decoration: BoxDecoration(
              color: _primaryLight,
              borderRadius: BorderRadius.circular(8),
              image: _ownerPhotoInfo['path'] != null
                  ? DecorationImage(
                      image: FileImage(File(_ownerPhotoInfo['path'])),
                      fit: BoxFit.cover,
                    )
                  : null,
            ),
            child: _ownerPhotoInfo['path'] == null
                ? Center(
                    child: Icon(Icons.person, size: 60, color: _primaryColor),
                  )
                : null,
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(context),
              child: Text('Close'),
            ),
          ],
        ),
      );
    }
  }

  void _removeOwnerPhoto() {
    _showConfirmationDialog(
      'Remove Photo',
      'Are you sure you want to remove this photo?',
      () {
        setState(() {
          _ownerPhotoInfo = {
            'name': '',
            'size': 0,
            'path': '',
            'uploaded': false,
          };
        });
      },
    );
  }

  Future<void> _pickFile(String fileType) async {
    try {
      FilePickerResult? result = await FilePicker.platform.pickFiles(
        type: FileType.custom,
        allowedExtensions: ['jpg', 'jpeg', 'png', 'pdf', 'doc', 'docx'],
        allowMultiple: false,
      );

      if (result != null && result.files.isNotEmpty) {
        final file = result.files.first;

        setState(() {
          switch (fileType) {
            case 'business':
              _businessRegInfo = {
                'name': file.name,
                'size': file.size,
                'path': file.path ?? '',
                'uploaded': true,
              };
              break;
            case 'ownership':
              _ownershipProofInfo = {
                'name': file.name,
                'size': file.size,
                'path': file.path ?? '',
                'uploaded': true,
              };
              break;
            case 'idproof':
              _idProofInfo = {
                'name': file.name,
                'size': file.size,
                'path': file.path ?? '',
                'uploaded': true,
              };
              break;
            case 'fire':
              _fireSafetyInfo = {
                'name': file.name,
                'size': file.size,
                'path': file.path ?? '',
                'uploaded': true,
              };
              break;
            case 'cancellation':
            case 'cheque':
              _cancelledChequeInfo = {
                'name': file.name,
                'size': file.size,
                'path': file.path ?? '',
                'uploaded': true,
              };
              break;
          }
        });

        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('File uploaded successfully'),
            backgroundColor: _successColor,
            duration: Duration(seconds: 2),
          ),
        );
      }
    } catch (e) {
      _showErrorDialog(
        'Upload Error',
        'Failed to upload file: ${e.toString()}',
      );
    }
  }

