  Future<void> _saveDigitalSignature() async {
    if (_signatureController.isEmpty) {
      _showErrorDialog(
        'No Signature',
        'Please draw your signature before saving.',
      );
      return;
    }

    try {
      final Uint8List? signatureData = await _signatureController.toPngBytes();

      if (signatureData != null) {
        setState(() {
          _digitalSignatureImage = signatureData;
          _hasDigitalSignature = true;
        });

        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('Digital signature saved successfully'),
            backgroundColor: _successColor,
            duration: Duration(seconds: 2),
          ),
        );
      }
    } catch (e) {
      _showErrorDialog(
        'Save Error',
        'Failed to save digital signature: ${e.toString()}',
      );
    }
  }

  void _clearDigitalSignature() {
    _signatureController.clear();
  }

  void _viewDigitalSignature() {
    if (_digitalSignatureImage != null) {
      showDialog(
        context: context,
        builder: (context) => AlertDialog(
          title: Row(
            children: [
              Icon(Icons.draw, color: Colors.purple),
              SizedBox(width: 8),
              Text('Digital Signature'),
            ],
          ),
          content: Container(
            width: 300,
            height: 150,
            decoration: BoxDecoration(
              border: Border.all(color: _borderColor),
              borderRadius: BorderRadius.circular(8),
            ),
            child: ClipRRect(
              borderRadius: BorderRadius.circular(8),
              child: Image.memory(_digitalSignatureImage!, fit: BoxFit.contain),
            ),
          ),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(context),
              child: Text('Close'),
            ),
          ],
        ),
      );
    }
  }

  void _removeDigitalSignature() {
    _showConfirmationDialog(
      'Remove Digital Signature',
      'Are you sure you want to remove the digital signature?',
      () {
        setState(() {
          _digitalSignatureImage = null;
          _hasDigitalSignature = false;
          _signatureController.clear();
        });
      },
    );
  }

  Future<void> _selectDate(BuildContext context) async {
    final DateTime? picked = await showDatePicker(
      context: context,
      initialDate: DateTime.now(),
      firstDate: DateTime(2000),
      lastDate: DateTime.now(),
    );
    if (picked != null && picked != _selectedDate) {
      setState(() {
        _selectedDate = picked;
      });
    }
  }

  Future<void> _selectAvailableFromDate(BuildContext context) async {
    final DateTime? picked = await showDatePicker(
      context: context,
      initialDate: DateTime.now(),
      firstDate: DateTime.now(),
      lastDate: DateTime(2100),
    );
    if (picked != null && picked != _availableFromDate) {
      setState(() {
        _availableFromDate = picked;
      });
    }
  }

  void _showErrorDialog(String title, String message) {
    showDialog(
      context: context,
      builder: (context) => AlertDialog(
        title: Text(title),
        content: Text(message),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: Text('OK'),
          ),
        ],
      ),
    );
  }

  void _showConfirmationDialog(
    String title,
    String message,
    VoidCallback onConfirm,
  ) {
    showDialog(
      context: context,
      builder: (context) => AlertDialog(
        title: Text(title),
        content: Text(message),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: Text('Cancel'),
          ),
          TextButton(
            onPressed: () {
              Navigator.pop(context);
              onConfirm();
            },
            child: Text('Confirm', style: TextStyle(color: Colors.red)),
          ),
        ],
      ),
    );
  }

  void _nextStep() {
    if (_currentStep < _steps.length - 1) {
      setState(() {
        _currentStep++;
      });
    } else {
      _submitForm();
    }
  }

  void _previousStep() {
    if (_currentStep > 0) {
      setState(() {
        _currentStep--;
      });
    }
  }



