class _VillaOwnerProfilePageState extends State<VillaOwnerProfilePage>
    with SingleTickerProviderStateMixin {
  late TabController _tabController;
  int _currentTabIndex = 0;

  // Villa specific colors
  final Color _primaryColor = const Color(0xFF00897B); // Teal
  final Color _primaryLight = const Color(0xFFE0F2F1); // Light teal
  final Color _accentColor = const Color(0xFF00BFA5);

  final List<String> _tabTitles = [
    'Profile Details',
    'Villa Details',
    'Amenities',
    'Pricing',
    'Documents',
  ];

  @override
  void initState() {
    super.initState();
    _tabController = TabController(length: _tabTitles.length, vsync: this);
    _tabController.addListener(() {
      setState(() {
        _currentTabIndex = _tabController.index;
      });
    });
  }

  @override
  void dispose() {
    _tabController.dispose();
    super.dispose();
  }

  void _goToNextTab() {
    if (_currentTabIndex < _tabTitles.length - 1) {
      _tabController.animateTo(_currentTabIndex + 1);
    }
  }

  void _goToPreviousTab() {
    if (_currentTabIndex > 0) {
      _tabController.animateTo(_currentTabIndex - 1);
    }
  }

