class _ApartmentOwnerProfilePageState extends State<ApartmentOwnerProfilePage>
    with SingleTickerProviderStateMixin {
  late TabController _tabController;
  int _currentTabIndex = 0;

  // Apartment specific colors
  final Color _primaryColor = const Color(0xFF5C6BC0); // Indigo
  final Color _primaryLight = const Color(0xFFE8EAF6); // Light Indigo
  final Color _accentColor = const Color(0xFF7986CB);

  final List<String> _tabTitles = [
    'Profile Details',
    'Apartment Details',
    'Amenities',
    'Pricing',
    'Documents',
  ];

  @override
  void initState() {
    super.initState();
    _tabController = TabController(length: _tabTitles.length, vsync: this);
    _tabController.addListener(() {
      setState(() {
        _currentTabIndex = _tabController.index;
      });
    });
  }

  @override
  void dispose() {
    _tabController.dispose();
    super.dispose();
  }

  void _goToNextTab() {
    if (_currentTabIndex < _tabTitles.length - 1) {
      _tabController.animateTo(_currentTabIndex + 1);
    }
  }

  void _goToPreviousTab() {
    if (_currentTabIndex > 0) {
      _tabController.animateTo(_currentTabIndex - 1);
    }
  }

  @override
  Widget build(BuildContext context) {
    // Extract values from registrationData
    String displayOwnerName = widget.ownerName;
    String displayApartmentName = widget.apartmentName;

    // If direct values are empty, try to get from registrationData
    if ((displayOwnerName.isEmpty || displayApartmentName.isEmpty) &&
        widget.registrationData.isNotEmpty) {
      print('Trying to extract from registrationData');
      print('registrationData keys: ${widget.registrationData.keys.toList()}');

      // Try to get from basicInfo
      if (widget.registrationData.containsKey('basicInfo')) {
        final basicInfo = widget.registrationData['basicInfo'] as Map;
        print('basicInfo keys: ${basicInfo.keys.toList()}');

        if (displayOwnerName.isEmpty && basicInfo.containsKey('ownerName')) {
          displayOwnerName = basicInfo['ownerName']?.toString() ?? '';
          print('Extracted ownerName from basicInfo: "$displayOwnerName"');
        }

        if (displayApartmentName.isEmpty &&
            basicInfo.containsKey('apartmentName')) {
          displayApartmentName = basicInfo['apartmentName']?.toString() ?? '';
          print(
            'Extracted apartmentName from basicInfo: "$displayApartmentName"',
          );
        }
      }

      // Try direct keys as fallback
      if (displayOwnerName.isEmpty &&
          widget.registrationData.containsKey('ownerName')) {
        displayOwnerName =
            widget.registrationData['ownerName']?.toString() ?? '';
      }

      if (displayApartmentName.isEmpty &&
          widget.registrationData.containsKey('apartmentName')) {
        displayApartmentName =
            widget.registrationData['apartmentName']?.toString() ?? '';
      }
    }

    print('=== ApartmentOwnerProfilePage DEBUG ===');
