  Widget _buildHouseRulesCard() {
    final List<Widget> rules = [];

    if (widget.smokingPolicy != null && widget.smokingPolicy!.isNotEmpty) {
      rules.add(_buildRuleItem('Smoking Policy', widget.smokingPolicy!));
    }
    if (widget.petPolicy != null && widget.petPolicy!.isNotEmpty) {
      rules.add(_buildRuleItem('Pet Policy', widget.petPolicy!));
    }
    if (widget.eventPolicy != null && widget.eventPolicy!.isNotEmpty) {
      rules.add(_buildRuleItem('Event Policy', widget.eventPolicy!));
    }
    if (widget.visitorPolicy != null && widget.visitorPolicy!.isNotEmpty) {
      rules.add(_buildRuleItem('Visitor Policy', widget.visitorPolicy!));
    }
    if (widget.quietHours != null && widget.quietHours!.isNotEmpty) {
      rules.add(_buildRuleItem('Quiet Hours', widget.quietHours!));
    }
    if (widget.additionalRules != null && widget.additionalRules!.isNotEmpty) {
      rules.add(_buildRuleItem('Additional Rules', widget.additionalRules!));
    }

    if (rules.isEmpty) {
      return Container(
        padding: const EdgeInsets.all(40),
        decoration: BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.circular(16),
          boxShadow: [
            BoxShadow(
              color: Colors.black.withOpacity(0.06),
              blurRadius: 16,
              offset: const Offset(0, 6),
            ),
          ],
        ),
        child: const Center(
          child: Text(
            'No house rules specified',
            style: TextStyle(color: Colors.grey),
          ),
        ),
      );
    }

    return Container(
      padding: const EdgeInsets.all(20),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(16),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withOpacity(0.06),
            blurRadius: 16,
            offset: const Offset(0, 6),
          ),
        ],
      ),
      child: Column(children: rules),
    );
  }

  Widget _buildRuleItem(String rule, String value) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 16),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Text(
            rule,
            style: const TextStyle(
              fontSize: 13,
              fontWeight: FontWeight.w600,
              color: Colors.black87,
            ),
          ),
          const SizedBox(height: 4),
          Text(
            value,
            style: const TextStyle(fontSize: 13, color: Colors.black54),
          ),
        ],
      ),
    );
  }

