  Widget _buildUploadedDocumentsCard() {
    final Map<String, Map<String, dynamic>> documents = {
      'Ownership Proof': widget.ownershipProof,
      'ID Proof': widget.idProof,
      'Cancelled Cheque': widget.cancelledCheque,
      'Cancellation Policy': widget.cancellationPolicy,
      'Calendar Sync': widget.calendarSync,
    };

    final uploadedDocs = documents.entries
        .where((entry) => entry.value['uploaded'] == true)
        .toList();

    if (uploadedDocs.isEmpty) {
      return Container(
        padding: const EdgeInsets.all(40),
        decoration: BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.circular(16),
          boxShadow: [
            BoxShadow(
              color: Colors.black.withOpacity(0.06),
              blurRadius: 16,
              offset: const Offset(0, 6),
            ),
          ],
        ),
        child: Column(
          children: [
            Icon(Icons.folder_open, size: 50, color: Colors.grey[400]),
            const SizedBox(height: 16),
            const Text(
              'No Documents Uploaded',
              style: TextStyle(
                fontSize: 16,
                fontWeight: FontWeight.w600,
                color: Colors.grey,
              ),
            ),
            const SizedBox(height: 8),
            const Text(
              'Upload documents to complete your profile',
              style: TextStyle(fontSize: 14, color: Colors.grey),
              textAlign: TextAlign.center,
            ),
          ],
        ),
      );
    }

    return Container(
      padding: const EdgeInsets.all(16),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(16),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withOpacity(0.06),
            blurRadius: 16,
            offset: const Offset(0, 6),
          ),
        ],
      ),
      child: Column(
        children: uploadedDocs.map((entry) {
          return Padding(
            padding: const EdgeInsets.only(bottom: 12),
            child: _buildUploadedDocItem(
              documentName: entry.key,
              fileInfo: entry.value,
            ),
          );
        }).toList(),
      ),
    );
  }

  Widget _buildUploadedDocItem({
    required String documentName,
    required Map<String, dynamic> fileInfo,
  }) {
    final fileName = fileInfo['name']?.toString() ?? 'Document';
    final fileSize = fileInfo['size'] ?? 0;

    IconData getIcon() {
      switch (documentName) {
        case 'Ownership Proof':
          return Icons.home;
        case 'ID Proof':
          return Icons.badge;
        case 'Cancelled Cheque':
          return Icons.account_balance;
        case 'Cancellation Policy':
          return Icons.policy;
        case 'Calendar Sync':
          return Icons.calendar_month;
        default:
          return Icons.description;
      }
    }

    Color getColor() {
      switch (documentName) {
        case 'Ownership Proof':
          return Colors.orange;
        case 'ID Proof':
          return Colors.blue;
        case 'Cancelled Cheque':
          return Colors.green;
        case 'Cancellation Policy':
          return Colors.purple;
        case 'Calendar Sync':
          return Colors.teal;
        default:
          return _primaryColor;
      }
    }

    return Container(
      padding: const EdgeInsets.all(12),
      decoration: BoxDecoration(
        color: Colors.grey[50],
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: Colors.grey[200]!),
      ),
      child: Row(
        children: [
          Container(
            width: 48,
            height: 48,
            decoration: BoxDecoration(
              color: getColor().withOpacity(0.1),
              borderRadius: BorderRadius.circular(12),
            ),
            child: Icon(getIcon(), size: 24, color: getColor()),
          ),
          const SizedBox(width: 12),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  documentName,
                  style: const TextStyle(
                    fontSize: 14,
                    fontWeight: FontWeight.w600,
                    color: Colors.black87,
                  ),
                ),
                const SizedBox(height: 4),
                Text(
                  fileName,
                  style: const TextStyle(fontSize: 12, color: Colors.grey),
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                ),
                const SizedBox(height: 2),
                Text(
                  '${(fileSize / 1024).toStringAsFixed(1)} KB',
                  style: const TextStyle(fontSize: 11, color: Colors.grey),
                ),
              ],
            ),
          ),
          Container(
            padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
            decoration: BoxDecoration(
              color: Colors.green.withOpacity(0.1),
              borderRadius: BorderRadius.circular(8),
            ),
            child: const Row(
              children: [
                Icon(Icons.check_circle, size: 12, color: Colors.green),
                SizedBox(width: 4),
                Text(
                  'Uploaded',
                  style: TextStyle(
                    fontSize: 11,
                    color: Colors.green,
                    fontWeight: FontWeight.w600,
                  ),
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

