  Widget _buildProfileImage() {
    final isUploaded = widget.ownerPhoto['uploaded'] == true;
    final path = widget.ownerPhoto['path'] as String?;

    if (isUploaded && path != null && path.isNotEmpty) {
      return Image.file(
        File(path),
        fit: BoxFit.cover,
        errorBuilder: (context, error, stackTrace) {
          return _buildDefaultProfileImage();
        },
      );
    }
    return _buildDefaultProfileImage();
  }

  Widget _buildDefaultProfileImage() {
    return Container(
      color: Colors.white.withOpacity(0.2),
