  Widget _buildBankRow(String label, String value, {bool isSensitive = false}) {
    String displayValue = value;
    if (value.isEmpty) displayValue = 'Not provided';
    if (isSensitive && value.isNotEmpty && value.length >= 4) {
      displayValue = '•••• ${value.substring(value.length - 4)}';
    }

    return Row(
      children: [
        Expanded(
          child: Text(
            label,
            style: const TextStyle(color: Colors.grey, fontSize: 14),
          ),
        ),
        Expanded(
          child: Text(
            displayValue,
            style: const TextStyle(
              color: Colors.black87,
              fontSize: 14,
              fontWeight: FontWeight.w600,
            ),
            textAlign: TextAlign.right,
          ),
        ),
      ],
    );
  }

  Widget _buildDeclarationRow(String label, String value) {
    return Row(
      children: [
        Expanded(
          child: Text(
            label,
            style: const TextStyle(color: Colors.grey, fontSize: 14),
          ),
        ),
        Expanded(
          child: Text(
            value,
            style: const TextStyle(
              color: Colors.black87,
              fontSize: 14,
              fontWeight: FontWeight.w600,
            ),
            textAlign: TextAlign.right,
          ),
        ),
      ],
    );
  }

  String _maskAccountNumber(String accountNumber) {
    if (accountNumber.isEmpty) return 'Not provided';
    if (accountNumber.length <= 4) return accountNumber;
    return 'XXXX XXXX ${accountNumber.substring(accountNumber.length - 4)}';
  }
}

class ApartmentOwnerDashboard extends StatefulWidget {
  final Map<String, dynamic> registrationData;

  // Basic Info
  final String apartmentName;
  final String ownerName;
  final String mobileNumber;
  final String email;
  final String? altMobile;
  final String? companyName;
  final String? website;

  // Location
  final String address;
  final String area;
  final String city;
  final String state;
  final String pincode;
  final String? googleMapLink;

  // Property Details
  final String propertyType;
  final String totalUnits;
  final String totalBedrooms;
  final String totalBathrooms;
  final String guestCapacity;
  final String? floorNumber;
  final String? totalFloors;
  final String? elevatorAvailable;
  final String? propertySize;
  final String? yearConstruction;
  final String description;

  // Amenities
  final Map<String, bool> apartmentAmenities;
  final List<String> customAmenities;

  // Pricing
  final String basePrice;
  final String? weeklyPrice;
  final String? monthlyPrice;
  final String weekendPrice;
  final String? peakPrice;
  final String securityDeposit;
  final String minimumStay;
  final String? advancePayment;
  final String? checkInTime;
  final String? checkOutTime;

  // Documents
  final Map<String, dynamic> cancellationPolicy;
  final Map<String, dynamic> ownershipProof;
  final Map<String, dynamic> idProof;
  final Map<String, dynamic> cancelledCheque;
  final Map<String, dynamic> calendarSync;

  // Availability
  final DateTime? availableFromDate;
  final String? blackoutDates;
  final String? instantBooking;

  // Media
  final Map<String, List<Map<String, dynamic>>> mediaFiles;
  final Map<String, dynamic> ownerPhoto;

  // House Rules
  final String? smokingPolicy;
  final String? petPolicy;
  final String? eventPolicy;
  final String? visitorPolicy;
  final String? quietHours;
  final String? additionalRules;

  // Signature
  final bool hasDigitalSignature;
  final Uint8List? digitalSignatureImage;
  final DateTime? declarationDate;
  final bool declarationAccepted;

  // Admin
  final String? vendorStatus;
  final bool featuredListing;
  final bool verifiedBadge;
  final double ratingScore;
  final String? remarks;

  const ApartmentOwnerDashboard({
    Key? key,
    required this.registrationData,
    required this.apartmentName,
    required this.ownerName,
    required this.mobileNumber,
    required this.email,
    this.altMobile,
    this.companyName,
    this.website,
    required this.address,
    required this.area,
    required this.city,
    required this.state,
    required this.pincode,
    this.googleMapLink,
    required this.propertyType,
    required this.totalUnits,
    required this.totalBedrooms,
    required this.totalBathrooms,
    required this.guestCapacity,
    this.floorNumber,
    this.totalFloors,
    this.elevatorAvailable,
    this.propertySize,
    this.yearConstruction,
    required this.description,
    required this.apartmentAmenities,
    required this.customAmenities,
    required this.basePrice,
    this.weeklyPrice,
    this.monthlyPrice,
    required this.weekendPrice,
    this.peakPrice,
    required this.securityDeposit,
    required this.minimumStay,
    this.advancePayment,
    this.checkInTime,
    this.checkOutTime,
    required this.cancellationPolicy,
    required this.ownershipProof,
    required this.idProof,
    required this.cancelledCheque,
    required this.calendarSync,
    this.availableFromDate,
    this.blackoutDates,
    this.instantBooking,
    required this.mediaFiles,
    required this.ownerPhoto,
    this.smokingPolicy,
    this.petPolicy,
    this.eventPolicy,
    this.visitorPolicy,
    this.quietHours,
    this.additionalRules,
    required this.hasDigitalSignature,
    this.digitalSignatureImage,
    this.declarationDate,
    required this.declarationAccepted,
    this.vendorStatus,
    required this.featuredListing,
    required this.verifiedBadge,
    required this.ratingScore,
    this.remarks,
  }) : super(key: key);

  @override
  State<ApartmentOwnerDashboard> createState() =>
      _ApartmentOwnerDashboardState();
}

class _ApartmentOwnerDashboardState extends State<ApartmentOwnerDashboard> {
  int _selectedIndex = 0;

  // Apartment specific colors
  final Color _primaryColor = const Color(0xFF5C6BC0); // Indigo
  final Color _primaryLight = const Color(0xFFE8EAF6); // Light Indigo
  final Color _accentColor = const Color(0xFF7986CB);
  final Color _bgColor = const Color(0xFFF9FAFB);
  final Color _cardBg = Colors.white;
  final Color _textDark = const Color(0xFF111827);
  final Color _textLight = const Color(0xFF6B7280);
  final Color _borderColor = const Color(0xFFE5E7EB);
  final Color _successColor = const Color(0xFF10B981);
  final Color _warningColor = const Color(0xFFF59E0B);
  final Color _dangerColor = const Color(0xFFEF4444);

  // Booking stats
  String _selectedMonth = 'January';
  List<String> _months = [
    'January',
    'February',
    'March',
    'April',
    'May',
    'June',
    'July',
    'August',
    'September',
    'October',
    'November',
    'December',
  ];

  @override
  Widget build(BuildContext context) {
    print('=== ApartmentOwnerDashboard _showProfile DEBUG ===');
    print('dashboard ownerName: "${widget.ownerName}"');
    print('dashboard apartmentName: "${widget.apartmentName}"');
    print('dashboard email: "${widget.email}"');
    print('dashboard mobileNumber: "${widget.mobileNumber}"');

    double w = MediaQuery.of(context).size.width;
    double h = MediaQuery.of(context).size.height;

    return WillPopScope(
      onWillPop: () async {
        Navigator.pushReplacement(
          context,
          MaterialPageRoute(
            builder: (context) =>
                PropertyAuthScreen(selectedPropertyType: 'apartment'),
          ),
        );
        return false;
      },
      child: Scaffold(
        backgroundColor: _bgColor,
        appBar: _buildAppBar(),
        drawer: _buildDrawer(w),
        body: _buildBody(w, h),
        bottomNavigationBar: _buildBottomNavigationBar(),
      ),
    );
  }

  AppBar _buildAppBar() {
    return AppBar(
      backgroundColor: _cardBg,
      elevation: 2,
      shadowColor: Colors.black12,
      leading: Builder(
        builder: (context) => Container(
          margin: const EdgeInsets.only(left: 16),
          child: IconButton(
            icon: Icon(Icons.menu_rounded, color: _primaryColor, size: 28),
