  void _initializeData() {
    final data = widget.registrationData;

    print('=== ApartmentEditProfileScreen INIT ===');
    print('Data keys: ${data.keys.toList()}');

    // Helper function to get nested values safely
    String _getString(dynamic value, String defaultValue) {
      if (value == null) return defaultValue;
      if (value is String) return value;
      if (value is num) return value.toString();
      if (value is bool) return value.toString();
      return defaultValue;
    }

    // Initialize Profile Details
    Map<String, dynamic> basicInfo = data['basicInfo'] is Map
        ? Map<String, dynamic>.from(data['basicInfo'])
        : {};

    _ownerNameController = TextEditingController(
      text: _getString(basicInfo['ownerName'] ?? data['ownerName'], ''),
    );
    _emailController = TextEditingController(
      text: _getString(basicInfo['email'] ?? data['email'], ''),
