          _buildSectionHeader('Booking Policies'),
          const SizedBox(height: 16),
          Row(
            children: [
              Expanded(
                child: _buildReadOnlyField(
                  label: 'Check-in Time',
                  value: _checkInTimeController.text.isNotEmpty
                      ? _checkInTimeController.text
                      : 'Not set',
                  icon: Icons.login,
                ),
