              const SizedBox(width: 12),
              Expanded(
                child: _buildReadOnlyField(
                  label: 'Check-out Time',
                  value: _checkOutTimeController.text.isNotEmpty
                      ? _checkOutTimeController.text
                      : 'Not set',
