  Widget _buildDocumentsTab() {
    return SingleChildScrollView(
      padding: const EdgeInsets.all(20),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          _buildSectionHeader('Legal Documents'),
          const SizedBox(height: 16),
          _buildReadOnlyField(
            label: 'GST Number',
            value: _gstNumberController.text.isNotEmpty
                ? _gstNumberController.text
                : 'Not provided',
            icon: Icons.receipt,
          ),
          const SizedBox(height: 16),
          _buildReadOnlyField(
            label: 'Trade License',
            value: _tradeLicenseController.text.isNotEmpty
                ? _tradeLicenseController.text
                : 'Not provided',
            icon: Icons.business,
          ),

          const SizedBox(height: 24),
          _buildSectionHeader('Bank Details'),
          const SizedBox(height: 16),
          _buildReadOnlyField(
            label: 'Account Holder',
            value: _accountHolderController.text.isNotEmpty
                ? _accountHolderController.text
                : 'Not provided',
            icon: Icons.person,
          ),
          const SizedBox(height: 16),
          _buildReadOnlyField(
            label: 'Bank Name',
            value: _bankNameController.text.isNotEmpty
                ? _bankNameController.text
                : 'Not provided',
