          ),
          const SizedBox(height: 16),
          _buildReadOnlyField(
            label: 'Account Number',
            value: _maskAccountNumber(_accountNumberController.text),
            icon: Icons.numbers,
          ),
          const SizedBox(height: 16),
          Row(
            children: [
              Expanded(
                child: _buildReadOnlyField(
                  label: 'IFSC Code',
                  value: _ifscCodeController.text.isNotEmpty
                      ? _ifscCodeController.text
                      : 'Not provided',
                  icon: Icons.code,
                ),
              ),
              const SizedBox(width: 12),
              Expanded(
                child: _buildReadOnlyField(
                  label: 'UPI ID',
                  value: _upiIdController.text.isNotEmpty
                      ? _upiIdController.text
                      : 'Not provided',
                  icon: Icons.payment,
                ),
              ),
            ],
          ),

          const SizedBox(height: 24),
          _buildSectionHeader('House Rules'),
          const SizedBox(height: 16),
          if (_smokingPolicyController.text.isNotEmpty)
            _buildRuleItem('Smoking Policy', _smokingPolicyController.text),
          if (_petPolicyController.text.isNotEmpty)
            _buildRuleItem('Pet Policy', _petPolicyController.text),
          if (_eventPolicyController.text.isNotEmpty)
            _buildRuleItem('Event Policy', _eventPolicyController.text),
          if (_visitorPolicyController.text.isNotEmpty)
            _buildRuleItem('Visitor Policy', _visitorPolicyController.text),
          if (_quietHoursController.text.isNotEmpty)
            _buildRuleItem('Quiet Hours', _quietHoursController.text),
          if (_additionalRulesController.text.isNotEmpty)
            _buildRuleItem('Additional Rules', _additionalRulesController.text),

          if (_smokingPolicyController.text.isEmpty &&
              _petPolicyController.text.isEmpty &&
              _eventPolicyController.text.isEmpty &&
              _visitorPolicyController.text.isEmpty &&
              _quietHoursController.text.isEmpty &&
