  final String pincode;
  final String? googleMapLink;
  final String? nearestAirport;
  final String? nearestRailway;

  // Property Details
  final String? resortCategory;
  final String totalRooms;
  final String totalCapacity;
  final Map<String, bool> roomTypes;
  final String? propertyArea;
  final String yearEstablished;
  final String description;

  // Amenities
  final Map<String, bool> resortAmenities;
