  final String? checkInTime;
  final String? checkOutTime;

  // Availability
  final String? instantBooking;
  final String? manualApproval;
  final DateTime? availableFromDate;
  final String? blackoutDates;
  final String? seasonalPricing;

  // Documents
  final Map<String, dynamic> cancellationPolicy;
  final Map<String, dynamic> businessReg;
  final Map<String, dynamic> ownershipProof;
  final Map<String, dynamic> idProof;
  final Map<String, dynamic> fireSafety;
  final Map<String, dynamic> cancelledCheque;

  // Media
  final Map<String, List<Map<String, dynamic>>> mediaFiles;
  final Map<String, dynamic> ownerPhoto;

  // House Rules
  final String? checkInRequirements;
  final String? idProofRequired;
  final String? petPolicy;
  final String? smokingPolicy;
  final String? eventPolicy;
  final String? damagePolicy;
  final String? refundPolicy;

  // Legal
  final String? gstNumber;
  final String? tradeLicense;
  final String? fssaiLicense;
  final String? tourismApproval;

  // Bank
  final String? accountHolderName;
  final String? bankName;
  final String? accountNumber;
  final String? ifscCode;
  final String? upiId;
  final String? gstBilling;

  // Signature
  final bool hasDigitalSignature;
  final Uint8List? digitalSignatureImage;
  final DateTime? declarationDate;
  final bool declarationAccepted;

  // Admin
  final String? vendorStatus;
  final bool featuredResort;
  final bool verifiedBadge;
  final double ratingScore;
  final String? priorityListingLevel;
  final String? remarks;

  const ResortOwnerDashboard({
    Key? key,
    required this.registrationData,
    required this.resortName,
    required this.ownerName,
    required this.contactPerson,
    required this.mobileNumber,
    required this.email,
    this.altMobile,
    this.website,
    this.companyName,
    required this.address,
    required this.area,
    required this.city,
    required this.state,
    required this.pincode,
    this.googleMapLink,
    this.nearestAirport,
    this.nearestRailway,
    this.resortCategory,
    required this.totalRooms,
    required this.totalCapacity,
    required this.roomTypes,
    this.propertyArea,
    required this.yearEstablished,
    required this.description,
    required this.resortAmenities,
    required this.customAmenities,
    required this.basePrice,
    required this.weekendPrice,
    this.peakPrice,
    this.extraBedCharges,
    this.childPolicy,
    required this.minimumStay,
    this.advancePayment,
    this.checkInTime,
    this.checkOutTime,
    this.instantBooking,
    this.manualApproval,
    this.availableFromDate,
    this.blackoutDates,
    this.seasonalPricing,
    required this.cancellationPolicy,
    required this.businessReg,
    required this.ownershipProof,
    required this.idProof,
    required this.fireSafety,
    required this.cancelledCheque,
    required this.mediaFiles,
    required this.ownerPhoto,
    this.checkInRequirements,
    this.idProofRequired,
    this.petPolicy,
    this.smokingPolicy,
    this.eventPolicy,
    this.damagePolicy,
    this.refundPolicy,
    this.gstNumber,
    this.tradeLicense,
    this.fssaiLicense,
    this.tourismApproval,
    this.accountHolderName,
    this.bankName,
    this.accountNumber,
    this.ifscCode,
    this.upiId,
    this.gstBilling,
    required this.hasDigitalSignature,
    this.digitalSignatureImage,
    this.declarationDate,
    required this.declarationAccepted,
    this.vendorStatus,
    required this.featuredResort,
    required this.verifiedBadge,
    required this.ratingScore,
    this.priorityListingLevel,
    this.remarks,
  }) : super(key: key);

  @override
  State<ResortOwnerDashboard> createState() => _ResortOwnerDashboardState();
