      MaterialPageRoute(
        builder: (context) => ResortEditProfileScreen(
          registrationData: widget.registrationData,
        ),
      ),
    );

    if (updatedData != null && updatedData is Map<String, dynamic>) {
      setState(() {});
    }
  }

