  String _getRoomTypesString() {
    final selectedTypes = widget.roomTypes.entries
        .where((entry) => entry.value == true)
        .map((entry) => entry.key)
        .toList();

    if (selectedTypes.isEmpty) return 'None selected';
    if (selectedTypes.length <= 3) return selectedTypes.join(', ');
    return '${selectedTypes.take(3).join(', ')} +${selectedTypes.length - 3} more';
  }

