  Widget _buildMediaGalleryCard() {
    final mediaKeys = {
      'exterior': 'Exterior Photos',
      'reception': 'Reception & Lobby',
      'rooms': 'Room Photos',
      'pool_amenities': 'Pool & Amenities',
      'restaurant': 'Restaurant Photos',
      'short_video': 'Short Video',
    };

    bool hasMedia = false;
    mediaKeys.forEach((key, label) {
      final files = widget.mediaFiles[key] ?? [];
      if (files.isNotEmpty) hasMedia = true;
    });

    if (!hasMedia) {
      return Container(
        padding: const EdgeInsets.all(40),
        decoration: BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.circular(16),
          boxShadow: [
            BoxShadow(
              color: Colors.black.withOpacity(0.06),
              blurRadius: 16,
              offset: const Offset(0, 6),
            ),
          ],
        ),
        child: const Center(
          child: Text(
            'No media files uploaded',
            style: TextStyle(color: Colors.grey),
          ),
        ),
      );
    }

    return Container(
      padding: const EdgeInsets.all(20),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(16),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withOpacity(0.06),
            blurRadius: 16,
            offset: const Offset(0, 6),
          ),
        ],
      ),
      child: Column(
        children: mediaKeys.entries.map((entry) {
          final key = entry.key;
          final label = entry.value;
          final files = widget.mediaFiles[key] ?? [];

          if (files.isEmpty) return const SizedBox.shrink();

          return Padding(
            padding: const EdgeInsets.only(bottom: 16),
            child: Row(
              children: [
                Container(
                  width: 50,
                  height: 50,
                  decoration: BoxDecoration(
                    color: key == 'short_video'
                        ? Colors.purple.withOpacity(0.1)
                        : _primaryLight,
                    borderRadius: BorderRadius.circular(12),
                  ),
                  child: Icon(
                    key == 'short_video'
                        ? Icons.video_library
                        : Icons.photo_library,
                    color: key == 'short_video' ? Colors.purple : _primaryColor,
                    size: 24,
                  ),
                ),
                const SizedBox(width: 12),
                Expanded(
                  child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(
                        label,
                        style: const TextStyle(
                          fontSize: 15,
                          fontWeight: FontWeight.w600,
                          color: Colors.black87,
                        ),
                      ),
                      const SizedBox(height: 4),
                      Text(
                        '${files.length} file(s) uploaded',
                        style: const TextStyle(
                          fontSize: 13,
                          color: Colors.grey,
                        ),
                      ),
                    ],
                  ),
                ),
                Container(
                  padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 4),
                  decoration: BoxDecoration(
                    color: Colors.green.withOpacity(0.1),
                    borderRadius: BorderRadius.circular(12),
                  ),
                  child: const Text(
                    'Uploaded',
                    style: TextStyle(
                      fontSize: 12,
                      color: Colors.green,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                ),
              ],
            ),
          );
        }).toList(),
      ),
    );
  }

