  Widget _buildHouseRulesCard() {
    final List<Widget> rules = [];

    if (widget.checkInRequirements != null && widget.checkInRequirements!.isNotEmpty) {
      rules.add(_buildRuleItem('Check-in Requirements', widget.checkInRequirements!));
    }
    if (widget.idProofRequired != null && widget.idProofRequired!.isNotEmpty) {
      rules.add(_buildRuleItem('ID Proof Required', widget.idProofRequired!));
    }
    if (widget.petPolicy != null && widget.petPolicy!.isNotEmpty) {
      rules.add(_buildRuleItem('Pet Policy', widget.petPolicy!));
    }
    if (widget.smokingPolicy != null && widget.smokingPolicy!.isNotEmpty) {
      rules.add(_buildRuleItem('Smoking Policy', widget.smokingPolicy!));
    }
    if (widget.eventPolicy != null && widget.eventPolicy!.isNotEmpty) {
      rules.add(_buildRuleItem('Event Policy', widget.eventPolicy!));
    }
    if (widget.damagePolicy != null && widget.damagePolicy!.isNotEmpty) {
      rules.add(_buildRuleItem('Damage Policy', widget.damagePolicy!));
    }
    if (widget.refundPolicy != null && widget.refundPolicy!.isNotEmpty) {
      rules.add(_buildRuleItem('Refund Policy', widget.refundPolicy!));
    }

    if (rules.isEmpty) {
      return Container(
        padding: const EdgeInsets.all(40),
        decoration: BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.circular(16),
          boxShadow: [
            BoxShadow(
              color: Colors.black.withOpacity(0.06),
              blurRadius: 16,
              offset: const Offset(0, 6),
            ),
          ],
        ),
        child: const Center(
          child: Text(
            'No house rules specified',
            style: TextStyle(color: Colors.grey),
          ),
        ),
      );
    }

    return Container(
      padding: const EdgeInsets.all(20),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(16),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withOpacity(0.06),
            blurRadius: 16,
            offset: const Offset(0, 6),
          ),
        ],
      ),
      child: Column(
        children: rules,
      ),
    );
  }

