  void _goToNextTab() {
    if (_currentTabIndex < _tabTitles.length - 1) {
      _tabController.animateTo(_currentTabIndex + 1);
    } else {
      _saveChanges();
    }
  }

  void _goToPreviousTab() {
    if (_currentTabIndex > 0) {
      _tabController.animateTo(_currentTabIndex - 1);
    }
  }

  Future<void> _saveChanges() async {
    // Build updated data map
    Map<String, dynamic> updatedData = Map.from(widget.registrationData);

    // Update ONLY the editable fields (amenities and room types)
    Map<String, dynamic> amenities = updatedData['amenities'] is Map
        ? Map<String, dynamic>.from(updatedData['amenities'])
        : {};

    amenities['selected'] = _resortAmenities;
    amenities['custom'] = _customAmenities;
    updatedData['amenities'] = amenities;

    // Update room types
    if (updatedData['propertyDetails'] is Map) {
      updatedData['propertyDetails']['roomTypes'] = _roomTypes;
    }

    // Also update description if you want it editable
    if (updatedData['propertyDetails'] is Map) {
      updatedData['propertyDetails']['description'] = _descriptionController.text;
    }

    // Update flat fields for backward compatibility
    updatedData['description'] = _descriptionController.text;

    // Save to SharedPreferences
    await _saveUser(updatedData);

    if (!mounted) return;

    ScaffoldMessenger.of(context).showSnackBar(
      const SnackBar(
        content: Text('Profile updated successfully!'),
        backgroundColor: Colors.green,
      ),
    );

    Navigator.pop(context, updatedData);
  }

  Future<void> _saveUser(Map<String, dynamic> userData) async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final String usersJson = prefs.getString('registered_users') ?? '[]';
      List<dynamic> users = jsonDecode(usersJson);

      final normalizedEmail = userData['email'].toString().toLowerCase().trim();
      userData['email'] = normalizedEmail;

      for (int i = 0; i < users.length; i++) {
        final existingEmail = users[i]['email']?.toString().toLowerCase().trim() ?? '';
        if (existingEmail == normalizedEmail) {
          users[i] = userData;
          break;
        }
      }

      await prefs.setString('registered_users', jsonEncode(users));
    } catch (e) {
      print('Error saving user: $e');
    }
  }

  void _addCustomAmenity() {
    if (_customAmenityController.text.trim().isNotEmpty) {
      setState(() {
        _customAmenities.add(_customAmenityController.text.trim());
        _customAmenityController.clear();
      });
    }
  }

  void _removeCustomAmenity(String amenity) {
    setState(() {
      _customAmenities.remove(amenity);
    });
  }

  void _updateRoomType(String type, bool value) {
    setState(() {
      _roomTypes[type] = value;
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: Colors.white,
      appBar: AppBar(
        title: const Text('Edit Resort Profile'),
        backgroundColor: _primaryColor,
        foregroundColor: Colors.white,
        elevation: 0,
        actions: [
          IconButton(
            icon: const Icon(Icons.save),
            onPressed: _saveChanges,
          ),
        ],
      ),
      body: Column(
        children: [
          Container(
            color: _primaryColor,
            child: TabBar(
              controller: _tabController,
              indicatorColor: Colors.white,
              indicatorWeight: 3,
              labelColor: Colors.white,
              unselectedLabelColor: Colors.white70,
              labelStyle: const TextStyle(fontWeight: FontWeight.w600, fontSize: 12),
              isScrollable: true,
              tabs: _tabTitles.map((title) {
                return Tab(text: title);
              }).toList(),
            ),
          ),
          Expanded(
            child: TabBarView(
              controller: _tabController,
              children: [
                _buildProfileDetailsTab(),    // READ-ONLY
                _buildResortDetailsTab(),     // READ-ONLY (except description)
                _buildAmenitiesTab(),          // EDITABLE
                _buildPricingTab(),            // READ-ONLY
                _buildDocumentsTab(),          // READ-ONLY
              ],
            ),
          ),
          _buildNavigationButtons(),
        ],
      ),
    );
  }

