  Widget _buildAmenitiesTab() {
    // Predefined amenities list
    final List<String> allAmenities = [
      'Swimming Pool',
      'Private Beach Access',
      'Spa & Wellness Center',
      'Gym',
      'Restaurant',
      'Bar',
      'Banquet Hall',
      'Conference Hall',
      'Free WiFi',
      'Air Conditioning',
      'Parking',
      '24/7 Front Desk',
      'Room Service',
      'Power Backup',
      'CCTV & Security',
      'Kids Play Area',
      'Outdoor Activities',
      'Indoor Games',
      'Airport Transfer',
      'Pet Friendly',
    ];

    return SingleChildScrollView(
      padding: const EdgeInsets.all(20),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          _buildSectionHeader('Select Amenities'),
          const SizedBox(height: 16),
          Container(
            decoration: BoxDecoration(
              color: Colors.white,
              borderRadius: BorderRadius.circular(12),
              border: Border.all(color: Colors.grey[300]!),
            ),
            child: Column(
              children: allAmenities.map((amenity) {
                return CheckboxListTile(
                  title: Text(amenity),
                  value: _resortAmenities[amenity] ?? false,
                  onChanged: (value) {
                    setState(() {
                      _resortAmenities[amenity] = value ?? false;
                    });
                  },
                  activeColor: _primaryColor,
                  checkboxShape: RoundedRectangleBorder(
                    borderRadius: BorderRadius.circular(4),
                  ),
                  controlAffinity: ListTileControlAffinity.leading,
                );
              }).toList(),
            ),
          ),

          const SizedBox(height: 24),
          _buildSectionHeader('Custom Amenities'),
          const SizedBox(height: 16),
          if (_customAmenities.isNotEmpty) ...[
            Container(
              decoration: BoxDecoration(
                color: Colors.white,
                borderRadius: BorderRadius.circular(12),
                border: Border.all(color: Colors.grey[300]!),
              ),
              child: ListView.separated(
                shrinkWrap: true,
                physics: const NeverScrollableScrollPhysics(),
                itemCount: _customAmenities.length,
                separatorBuilder: (context, index) => Divider(height: 1, color: Colors.grey[300]),
                itemBuilder: (context, index) {
                  return ListTile(
                    title: Text(_customAmenities[index]),
                    trailing: IconButton(
                      icon: const Icon(Icons.delete, color: Colors.red),
                      onPressed: () {
                        _removeCustomAmenity(_customAmenities[index]);
                      },
                    ),
                  );
                },
              ),
            ),
            const SizedBox(height: 16),
          ],

          Container(
            decoration: BoxDecoration(
              color: Colors.white,
              borderRadius: BorderRadius.circular(12),
              border: Border.all(color: Colors.grey[300]!),
            ),
            child: Row(
              children: [
                Expanded(
                  child: TextField(
                    controller: _customAmenityController,
                    decoration: const InputDecoration(
                      hintText: 'Add custom amenity',
                      border: InputBorder.none,
                      contentPadding: EdgeInsets.symmetric(horizontal: 16, vertical: 14),
                    ),
                    onSubmitted: (_) => _addCustomAmenity(),
                  ),
                ),
                IconButton(
                  icon: Icon(Icons.add_circle, color: _primaryColor, size: 28),
                  onPressed: _addCustomAmenity,
                ),
              ],
            ),
          ),
        ],
      ),
    );
  }

